        config = toml.load(f)
    return config

def run_build_backend(config):
    build_backend = config.get('tool', {}).get('poetry', {}).get('build_backend')
    if build_backend:
        if build_backend == 'poetry':
            subprocess.run(['poetry', 'build'], check=True)
        elif build_backend == 'setuptools':
            subprocess.run(['python', '-m', 'setuptools', 'build'], check=True)
        elif build_backend == 'twine':
            subprocess.run(['twine', 'upload'], check=True)
        # Add more build backends as needed
    else:
        print("No build backend specified in pyproject.toml")

def main():
    toml_file = 'pyproject.toml'
    config = parse_pyproject(toml_file)
    run_build_backend(config)

if __name__ == "__main__":
    main()
