import re

class Regex:
    def __init__(self, pattern):
        self.pattern = pattern

    def match(self, string):
        return bool(re.match(self.pattern, string))

    def replace(self, string, replacement):
        return re.sub(self.pattern, replacement, string)

    def split(self, string):
        return re.split(self.pattern, string)

    def search(self, string):
        return re.search(self.pattern, string)

    def findall(self, string):
        return re.findall(self.pattern, string)

    def finditer(self, string):
        return re.finditer(self.pattern, string)

    def subn(self, string, replacement):
        return re.subn(self.pattern, replacement, string)

# Example usage
if __name__ == "__main__":
    regex = Regex(r'\d+')
    print(regex.match('123'))  # True
    print(regex.replace('123', 'abc'))  # 'abc'
    print(regex.split('1,2,3'))  # ['','','']
    print(regex.search('hello world'))  # None
    print(regex.findall('hello world'))  # ['hello', 'world']
    print(list(regex.finditer('hello world')))  # <re.MatchObject: ...>
    print(regex.subn('123', 'abc'))  # ('', 'abc')
