import jsonschema
from jsonschema.exceptions import ValidationError
from jsonschema.validators import Draft7Validator

class CustomValidator(Draft7Validator):
    def __init__(self, schema, **kwargs):
        self._schema = schema
        super().__init__(schema, **kwargs)

    def _validate(self, data, path=""):
        result = super()._validate(data, path)
        if result is not None:
            return result
        return self._validate_properties(data, path)

    def _validate_properties(self, data, path=""):
        for prop, schema in self._schema.get("properties", {}).items():
            if isinstance(schema, dict):
                self._validate(data.get(prop, {}), path + "." + prop)
            else:
                if data.get(prop) != schema:
                    raise ValidationError(f"Property '{prop}' has an unexpected value", path + "." + prop)
        return None


def validate_json(json_data, schema):
    try:
        validator = CustomValidator(schema)
        validator.validate(json_data)
        print("JSON is valid")
    except ValidationError as e:
        print(f"JSON is invalid: {e}")
