import hatch
import git

class GitVersionPlugin(hatch.plugins.BasePlugin):
    def __init__(self, *args, **kwargs):
        self.git_repo = None
        super().__init__(*args, **kwargs)

    def get_name(self):
        return 'git-version'

    def get_version(self):
        if not self.git_repo:
            raise hatch.exceptions.PluginError("No Git repository specified")

        repo = self.git_repo
        try:
            return repo.head.hexsha
        except git.exc.InvalidGitRepositoryError:
            raise hatch.exceptions.PluginError("Invalid Git repository")

    def get_tags(self):
        if not self.git_repo:
            raise hatch.exceptions.PluginError("No Git repository specified")

        repo = self.git_repo
        try:
            return [tag.hexsha for tag in repo.tags]
        except git.exc.InvalidGitRepositoryError:
            raise hatch.exceptions.PluginError("Invalid Git repository")

    def set_version(self, version):
        if not self.git_repo:
            raise hatch.exceptions.PluginError("No Git repository specified")

        repo = self.git_repo
        repo.head.commit.hexsha = version
        repo.index.add([self.get_version()])
        repo.index.commit('update version to ' + version)

    def get_dependencies(self):
        if not self.git_repo:
            raise hatch.exceptions.PluginError("No Git repository specified")

        repo = self.git_repo
        return [repo.git.revparsebranch('master')]

    def get_dependencies_version(self):
        if not self.git_repo:
            raise hatch.exceptions.PluginError("No Git repository specified")

        repo = self.git_repo
        return repo.git.describe('master')

    def configure(self, config):
        config.set('git-repo', self.git_repo)

    def validate(self, config):
        if config.get('git-repo') is None:
            raise hatch.exceptions.PluginError("Git repository must be specified")

    def create(self, config):
        self.git_repo = git.Repo(config.get('git-repo'))

    def destroy(self, config):
        if self.git_repo:
            self.git_repo = None
