import os

class Path:
    def __init__(self, *args):
        self.path_components = list(args)

    def join(self, *args):
        return Path(*[self.path_components + list(args)])

    def separate(self):
        return '/'.join(self.path_components)

    def normalize(self):
        return os.path.normpath(self.separate())

    def __str__(self):
        return os.path.join(*self.path_components)


# Example usage:
path = Path('Users', 'username', 'Documents', 'example.txt')
print(path)  # Output: /Users/username/Documents/example.txt

path_separated = path.separate()
print(path_separated)  # Output: Users/username/Documents/example.txt

path_normalized = path.normalize()
print(path_normalized)  # Output: /Users/username/Documents/example.txt
