import os

class Settings(BaseSettings):
    """Base settings model"""
    API_URL: str = "https://example.com/api"
    DEBUG: bool = True

class SettingsFile(BaseSettings):
    """Settings model loaded from a file"""
    API_URL: str
    DEBUG: bool

