        if os.path.exists(self.settings_file):
            with open(self.settings_file, "r") as f:
                return SettingsFile.parse_raw(f.read())
        else:
            return Settings()

class SettingsManager(BaseSettings):
    """Settings manager"""
    settings_base = SettingsBase()

    @property
    def settings(self):
        return self.settings_base.settings

def parse_args():
    """Parse command line arguments"""
    parser = argparse.ArgumentParser()
    parser.add_argument("--debug", action="store_true", help="Enable debug mode")
    args = parser.parse_args()
    return args.debug

def load_settings():
    """Load settings from file or command line arguments"""
    settings_manager = SettingsManager()
    debug = parse_args()
    if debug:
        settings_manager.settings_file = "settings.json.debug"
    return settings_manager.settings

def main():
    """Main function"""
    settings = load_settings()
    print(settings)

