class YpyDocument:
    def __init__(self, name, collaborators=None):
        self.name = name
        self.collaborators = collaborators if collaborators else []
        self.sections = {}
        self.changes = {}

    def add_section(self, title, content):
        self.sections[title] = content
        self.changes[title] = {"added": True}

    def remove_section(self, title):
        if title in self.sections:
            del self.sections[title]
            self.changes[title] = {"removed": True}
        else:
            print(f"Section '{title}' not found.")

    def add_collaborator(self, name):
        if name not in self.collaborators:
            self.collaborators.append(name)
            self.changes[name] = {"added": True}
        else:
            print(f"Collaborator '{name}' already exists.")

    def remove_collaborator(self, name):
        if name in self.collaborators:
            self.collaborators.remove(name)
            self.changes[name] = {"removed": True}
        else:
            print(f"Collaborator '{name}' not found.")

    def track_changes(self):
        print("Document changes:")
        for name, change in self.changes.items():
            if change["added"]:
                print(f"Added collaborator '{name}'")
            elif change["removed"]:
                print(f"Removed collaborator '{name}'")
            else:
                print(f"Updated collaborator '{name}'")

# Example usage:
document = YpyDocument("My Document")
document.add_section("Introduction", "This is the introduction.")
document.add_collaborator("John Doe")
document.add_collaborator("Jane Doe")
document.track_changes()
document.remove_collaborator("John Doe")
document.remove_section("Introduction")
document.track_changes()
```

