import argparse
import subprocess
import os

def pyright_wrapper(args):
    if not os.path.exists('.pyright'):
        print("No .pyright file found in the current directory.")
        return

    try:
        with open('.pyright', 'r') as f:
            rights = f.read()
    except FileNotFoundError:
        print("No .pyright file found in the current directory.")
        return

    subprocess.run(['pyright', '--', '.pyright'], input=rights.encode())

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="A CLI tool for running pyright on your files.")
    parser.add_argument('files', nargs='*', help='Files to check for rights')
    args = parser.parse_args()

    if args.files:
        for file in args.files:
            if not os.path.exists(file):
                print(f"File '{file}' not found.")
                continue
            try:
                with open(file, 'r') as f:
                    content = f.read()
            except Exception as e:
                print(f"Error reading file '{file}': {str(e)}")
                continue

            try:
                pyright_wrapper(content)
            except Exception as e:
                print(f"Error running pyright on file '{file}': {str(e)}")
    else:
        print("Please provide one or more files to check for rights.")
