import ast

def analyze_source_code(source_code):
    try:
        tree = ast.parse(source_code)
        return _analyze_tree(tree)
    except SyntaxError as e:
        print(f"Syntax error: {e}")
        return None

def _analyze_tree(node, parent=None, indent=0):
    if isinstance(node, ast.Module):
        return _analyze_frames(node)
    elif isinstance(node, ast.FunctionDef):
        return _analyze_frames(node, parent)
    elif isinstance(node, ast.ClassDef):
        return _analyze_frames(node, parent)
    else:
        return _format_node(node, indent)

def _analyze_frames(node, parent=None):
    frames = []
    for child in ast.walk(node):
        if isinstance(child, (ast.FunctionDef, ast.ClassDef)) and child.parent != node:
            frames.append((child, parent))
    return frames

def _format_node(node, indent):
    return f"{indent}  {node.__class__.__name__}: {node.__doc__}"

def print_api_documentation(frames):
    for frame, parent in frames:
        print(f"Function {frame.name}")
        print(f"  Parameters: {frame.args.args}")
        print(f"  Returns: {frame.returns}")
        print(f"  Parent: {parent.__class__.__name__}")

def print_breaking_changes(frames):
    for frame, parent in frames:
        if frame.name != parent.name:
            print(f"Breaking change: Function {frame.name} is defined in a different module than its parent {parent.name}")

source_code = """
def greet(name: str) -> None:
    print(f"Hello, {name}!")

class Person:
    def __init__(self, name: str):
        self.name = name
"""
print("API Documentation:")
frames = analyze_source_code(source_code)
if frames:
    print_api_documentation(frames)

print("\nBreaking Changes:")
print_breaking_changes(frames)
