import markdown
import importlib
import sys

class MarkdownParser:
    def __init__(self, text, plugins=None):
        self.text = text
        self.plugins = plugins if plugins else []

    def parse(self):
        for plugin in self.plugins:
            self.text = plugin(self.text)
        return markdown.markdown(self.text)

class Plugin:
    def __init__(self, name):
        self.name = name

    def __call__(self, text):
        raise NotImplementedError

class Extension(Plugin):
    def __init__(self, name, extension):
        super().__init__(name)
        self.extension = extension

    def __call__(self, text):
        raise NotImplementedError

class PluginManager:
    def __init__(self):
        self.plugins = []

    def add_plugin(self, plugin):
        self.plugins.append(plugin)

    def remove_plugin(self, plugin_name):
        self.plugins = [p for p in self.plugins if p.name != plugin_name]

    def get_plugin(self, plugin_name):
        for plugin in self.plugins:
            if plugin.name == plugin_name:
                return plugin
        return None

class MarkdownParserAPI:
    def __init__(self):
        self.parser_manager = PluginManager()

    def add_plugin(self, plugin):
        self.parser_manager.add_plugin(plugin)

    def remove_plugin(self, plugin_name):
        self.parser_manager.remove_plugin(plugin_name)

    def get_plugin(self, plugin_name):
        return self.parser_manager.get_plugin(plugin_name)

    def create_parser(self, text, plugins=None):
        return MarkdownParser(text, plugins)

# Example usage:
if __name__ == "__main__":
    parser_api = MarkdownParserAPI()

    # Define a plugin to convert headings to bold
    class HeadingPlugin(Extension):
        def __init__(self, extension):
            super().__init__("heading_plugin", extension)
            self.extension = extension

        def __call__(self, text):
            import re
            return re.sub(r"^(#+) (.*)$", lambda match: f"**{match.group(2)}**", text, flags=re.MULTILINE)

    plugin = HeadingPlugin("heading_plugin")
    parser_api.add_plugin(plugin)

    # Create a parser with the plugin
    parser = parser_api.create_parser("# Heading", plugins=[plugin])

    # Parse the text
    parsed_text = parser.parse()
    print(parsed_text)
