import threading
from typing import Callable, Observable, Observer, Any

class Observable:
    def __init__(self):
        self._subscribers = []
        self._is_completed = False

    def subscribe(self, observer: Observer):
        self._subscribers.append(observer)

    def unsubscribe(self, observer: Observer):
        self._subscribers.remove(observer)

    def on_next(self, value):
        for observer in self._subscribers:
            observer.on_next(value)

    def on_error(self, error):
        for observer in self._subscribers:
            observer.on_error(error)

    def on_completed(self):
        self._is_completed = True
        for observer in self._subscribers:
            observer.on_completed()

    def __iter__(self):
        return self

    def __next__(self):
        if self._is_completed:
            raise StopIteration
        for observer in self._subscribers:
            if not observer.is_subscribed():
                return next(observer)
        return next(self)


class Observer:
    def on_next(self, value):
        pass

    def on_error(self, error):
        pass

    def on_completed(self):
        pass

    def is_subscribed(self):
        return True


class Scheduler:
    def __init__(self):
        self._thread = threading.Thread(target=self._run)
        self._thread.daemon = True
        self._thread.start()

    def _run(self):
        import time
        while True:
            time.sleep(0.1)

    def schedule(self, callback, delay=0):
        import time
        time.sleep(delay)
        callback()


def defer(value):
    return Observable(lambda: value)


def from_iterable(iterable):
    return Observable(lambda: next(iterable))


def from_callable(callback):
    return Observable(lambda: callback())


def from_interval(interval):
    scheduler = Scheduler()
    return Observable(lambda: scheduler.schedule(lambda: None, interval))


def from_timer(duration):
    scheduler = Scheduler()
    return Observable(lambda: scheduler.schedule(lambda: None, duration))


def merge(*observables):
    merged = Observable(lambda: None)
    for observable in observables:
        merged.subscribe(lambda value: observable.on_next(value))
    return merged


def flat_map(observable, mapping):
    return Observable(lambda: mapping(observable))


def filter(observable, predicate):
    return Observable(lambda: observable.on_next(predicate(observable)))


def take(n):
    def wrapper(observable):
        for _ in range(n):
            observable.next()
    return wrapper


def concat(*observables):
    return Observable(lambda: next(observables, None))


def switch_to_new_thread(observable):
    def wrapper(observer):
        import threading
        def on_next(value):
            observer.on_next(value)
        def on_error(error):
            observer.on_error(error)
        def on_completed():
            observer.on_completed()
        threading.Thread(target=lambda: observable.on_next(on_next), args=(on_next,)).start()
        threading.Thread(target=lambda: observable.on_next(on_error), args=(on_error,)).start()
        threading.Thread(target=lambda: observable.on_next(on_completed), args=(on_completed,)).start()
    return Observer(wrapper)


# Example usage:
def on_next(value):
    print(value)

def on_error(error):
    print(error)

def on_completed():
    print("Completed")

observable = Observable()
observable.subscribe(switch_to_new_thread(on_next))
observable.subscribe(switch_to_new_thread(on_error))
observable.subscribe(switch_to_new_thread(on_completed))

observable.on_next("Value 1")
observable.on_next("Value 2")
observable.on_next("Value 3")

observable.on_error("Error")

observable.on_completed()
```

