import pandas as pd
import numpy as np

def clean_data(df):
    """Clean the data by removing duplicates and handling missing values"""
    df = df.drop_duplicates()
    df = df.fillna(df.mean())
    return df

def transform_data(df):
    """Transform the data by converting columns to appropriate data types"""
    df['column1'] = pd.to_numeric(df['column1'])
    df['column2'] = pd.to_datetime(df['column2'])
    return df

def load_data(file_path):
    """Load data from a file into a pandas DataFrame"""
    return pd.read_csv(file_path)

def data_wrangling(df, column_name):
    """Perform data wrangling by filtering and grouping data"""
    df = df[df[column_name] > 0]
    return df.groupby(column_name).sum()

def merge_data(df1, df2, on):
    """Merge two DataFrames based on a common column"""
    return pd.merge(df1, df2, on=on)

def join_data(df1, df2, on):
    """Join two DataFrames based on a common column"""
    return pd.merge(df1, df2, on=on, how='inner')

def reshape_data(df):
    """Reshape the data by pivoting and melting"""
    return df.pivot(index='column1', columns='column2', values='column3').melt(id_vars='column1', value_vars='column2')

# Example usage:
df = pd.DataFrame({
    'column1': [1, 2, 3, 4],
    'column2': ['a', 'b', 'c', 'd'],
    'column3': [10, 20, 30, 40]
})

cleaned_df = clean_data(df)
transformed_df = transform_data(cleaned_df)
loaded_df = load_data('data.csv')
wrangled_df = data_wrangling(loaded_df, 'column1')
merged_df = merge_data(loaded_df, loaded_df, 'column1')
joined_df = join_data(loaded_df, loaded_df, 'column1')
reshaped_df = reshape_data(loaded_df)
