        self.G = nx.Graph()

    def add_node(self, node):
        self.G.add_node(node)

    def remove_node(self, node):
        if node in self.G.nodes():
            self.G.remove_node(node)
        else:
            print(f"Node {node} does not exist in the graph.")

    def add_edge(self, node1, node2):
        if node1 in self.G.nodes() and node2 in self.G.nodes():
            self.G.add_edge(node1, node2)
        else:
            print(f"Both nodes {node1} and {node2} do not exist in the graph.")

    def remove_edge(self, node1, node2):
        if node1 in self.G.nodes() and node2 in self.G.nodes():
            self.G.remove_edge(node1, node2)
        else:
            print(f"One of the nodes {node1} or {node2} does not exist in the graph.")

    def get_nodes(self):
        return list(self.G.nodes())

    def get_edges(self):
        return list(self.G.edges())

    def get_neighbors(self, node):
        return list(self.G.neighbors(node))

# Example usage
