import json

class JSONPathParser:
    def __init__(self, json_path):
        self.json_path = json_path

    def parse(self):
        nodes = self._parse_path_components(self.json_path)
        return self._build_ast(nodes)

    def _parse_path_components(self, path):
        components = []
        current_node = self.json_path
        for component in path.split('/'):
            if component == '*':
                # Split the current node into multiple children
                children = self._get_children(current_node)
                for child in children:
                    components.append(child)
                    current_node = child
            elif component == '?':
                # Find the first matching child
                children = self._get_children(current_node)
                for child in children:
                    components.append(child)
                    current_node = child
                    break
            else:
                # Get the child node by its key
                children = self._get_children(current_node)
                if len(children) == 0 or children[0]['$key'] != component:
                    return []
                components.append(children[0])
                current_node = children[0]
        return components

    def _get_children(self, node):
        if isinstance(node, dict):
            return [node]
        elif isinstance(node, list):
            return node
        else:
            return []

    def _build_ast(self, nodes):
        class Node:
            def __init__(self, value):
                self.value = value

        class BinaryOperator(Node):
            def __init__(self, left, operator, right):
                self.left = left
                self.operator = operator
                self.right = right

        class ArithmeticOperator(Node):
            def __init__(self, left, operator, right):
                self.left = left
                self.operator = operator
                self.right = right

        class ComparisonOperator(Node):
            def __init__(self, left, operator, right):
                self.left = left
                self.operator = operator
                self.right = right

        class EqualityOperator(Node):
            def __init__(self, left, operator, right):
                self.left = left
                self.operator = operator
                self.right = right

        ast = nodes[0]
        for node in nodes[1:]:
            if isinstance(node, str):
                # Path component
                if node in ['*', '?']:
                    ast = BinaryOperator(ast, node, ast)
                else:
                    ast = BinaryOperator(ast, '=', node)
            elif isinstance(node, dict):
                # Object property
                ast = BinaryOperator(ast, '=', node)
            elif isinstance(node, list):
                # Array index
                ast = BinaryOperator(ast, '=', node)
            else:
                raise ValueError('Invalid node type')
        return ast


class JSONPathEvaluator:
    def __init__(self, json_data, ast):
        self.json_data = json_data
        self.ast = ast

    def evaluate(self):
        self._evaluate_ast(self.ast)
        return self.json_data

    def _evaluate_ast(self, ast):
        if isinstance(ast, Node):
            if ast.value in ['*', '?']:
                # Evaluate the children
                children = [self._evaluate_child(child) for child in self._get_children(ast)]
                return children[0] if ast.value == '*' else children[0] if len(children) > 0 else None
            elif ast.value == '=':
                # Evaluate the right-hand side
                right = self._evaluate_ast(ast.right)
                return right if right is not None else None
            else:
                raise ValueError('Invalid operator')
        elif isinstance(ast, BinaryOperator):
            left = self._evaluate_ast(ast.left)
            right = self._evaluate_ast(ast.right)
            if isinstance(ast, ArithmeticOperator):
                # Evaluate the arithmetic expression
                return self._evaluate_arithmetic_expression(left, right, ast.operator)
            elif isinstance(ast, ComparisonOperator):
                # Evaluate the comparison expression
                return self._evaluate_comparison_expression(left, right, ast.operator)
            else:
                raise ValueError('Invalid operator')
        elif isinstance(ast, ArithmeticOperator):
            # Evaluate the arithmetic expression
            return self._evaluate_arithmetic_expression(ast.left, ast.right, ast.operator)
        elif isinstance(ast, ComparisonOperator):
            # Evaluate the comparison expression
            return self._evaluate_comparison_expression(ast.left, ast.right, ast.operator)
        else:
            raise ValueError('Invalid node type')

    def _evaluate_child(self, child):
        if isinstance(child, dict):
            # Object property
            return child
        elif isinstance(child, list):
            # Array index
            return child
        else:
            return child

    def _evaluate_arithmetic_expression(self, left, right, operator):
        if operator == '+':
            return left + right
        elif operator == '-':
            return left - right
        elif operator == '*':
            return left * right
        elif operator == '/':
            return left / right
        else:
            raise ValueError('Invalid operator')

    def _evaluate_comparison_expression(self, left, right, operator):
        if operator == '==':
            return left == right
        elif operator == '!=':
            return left != right
        elif operator == '>':
            return left > right
        elif operator == '<':
            return left < right
        elif operator == '>=':
            return left >= right
        elif operator == '<=':
            return left <= right
        else:
            raise ValueError('Invalid operator')


# Example usage:
json_path = "/users[*]/name"
json_data = {'users': [{'name': 'John'}, {'name': 'Jane'}]}
parser = JSONPathParser(json_data)
ast = parser.parse()
evaluator = JSONPathEvaluator(json_data, ast)
result = evaluator.evaluate()
print(result)  # Output: ['John', 'Jane']
```

