import os
import argparse
import json

class Configuration:
    def __init__(self):
        self.config = {}
        self.env_vars = {}
        self.cmd_args = None

    def read_env_vars(self):
        for key in os.environ:
            self.env_vars[key] = os.environ[key]

    def read_cmd_args(self):
        parser = argparse.ArgumentParser(description='Tool configuration')
        parser.add_argument('-c', '--config', help='Path to configuration file', required=True)
        parser.add_argument('-e', '--env-vars', help='Path to environment variables file', required=True)
        args = parser.parse_args()
        self.cmd_args = vars(args)
        self.read_config_from_file(self.cmd_args['config'])
        self.read_config_from_file(self.cmd_args['env-vars'])

    def read_config_from_file(self, file_path):
        try:
            with open(file_path, 'r') as f:
                self.config = json.load(f)
        except FileNotFoundError:
            print(f"Configuration file not found: {file_path}")
            exit(1)
        except json.JSONDecodeError:
            print(f"Invalid configuration file: {file_path}")
            exit(1)

    def get_config(self, key):
        if key in self.config:
            return self.config[key]
        elif key in self.env_vars:
            return self.env_vars[key]
        elif self.cmd_args.get(key):
            return self.cmd_args[key]
        else:
            return None

# Example usage:
config = Configuration()
config.read_env_vars()
config.read_cmd_args()
print(config.get_config('tool_name'))
