import subprocess
import threading
import time

class PseudoTerminal:
    def __init__(self, cmd, timeout=10):
        self.cmd = cmd
        self.timeout = timeout
        self.stdin = subprocess.PIPE
        self.stdout = subprocess.PIPE
        self.stderr = subprocess.PIPE

    def spawn(self):
        self.process = subprocess.Popen(self.cmd, shell=True, stdin=self.stdin, stdout=self.stdout, stderr=self.stderr, universal_newlines=True, buffer_size=1024)

    def expect(self, pattern):
        while True:
            line = self.process.stdout.readline()
            if pattern in line:
                return line.strip()
            time.sleep(0.1)

    def interact(self):
        self.spawn()
        while True:
            user_input = input()
            self.process.stdin.write(user_input + '\n')
            self.process.stdin.flush()
            result = self.expect('exit')
            if result:
                print(result)
                break

