import requests
import json
from dataclasses import dataclass

class OntapAPI:
    def __init__(self, hostname, username, password):
        self.hostname = hostname
        self.username = username
        self.password = password
        self.base_url = f"http://{hostname}/api"

    def create_volume(self, volume_name, volume_size):
        data = {
            "volume": {
                "name": volume_name,
                "size": volume_size
            }
        }
        headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }
        response = requests.post(f"{self.base_url}/volumes", headers=headers, data=json.dumps(data))
        if response.status_code == 201:
            return json.loads(response.content)
        else:
            raise Exception("Failed to create volume")

    def create_snapshot(self, volume_name, snapshot_name):
        data = {
            "snapshot": {
                "name": snapshot_name,
                "volume": {
                    "name": volume_name
                }
            }
        }
        headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }
        response = requests.post(f"{self.base_url}/snapshots", headers=headers, data=json.dumps(data))
        if response.status_code == 201:
            return json.loads(response.content)
        else:
            raise Exception("Failed to create snapshot")

    def get_volumes(self):
        headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }
        response = requests.get(f"{self.base_url}/volumes", headers=headers)
        if response.status_code == 200:
            return response.json()["result"]
        else:
            raise Exception("Failed to get volumes")

    def get_snapshots(self, volume_name):
        headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }
        response = requests.get(f"{self.base_url}/snapshots", headers=headers)
        if response.status_code == 200:
            return [snapshot for snapshot in response.json()["result"] if snapshot["volume"]["name"] == volume_name]
        else:
            raise Exception("Failed to get snapshots")

    def delete_snapshot(self, snapshot_name):
        headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json'
        }
        response = requests.delete(f"{self.base_url}/snapshots/{snapshot_name}", headers=headers)
        if response.status_code == 204:
            return True
        else:
            raise Exception("Failed to delete snapshot")

