import re
import requests

def get_user_agent(user_agent):
    # Define a dictionary of common user agents
    user_agents = {
        'desktop': ['Windows NT 10.0; Win64; x64', 'Macintosh; Intel Mac OS X 12_4', 'Linux x86_64'],
        'mobile': ['Windows Phone 10.0; Windows Phone 10.0; Windows NT 10.0; Win64; ARMv7; rev.1', 
                   'iPhone; CPU iPhone OS 15_4 like Mac OS X', 'Android; Android 11; SM-G960F; en_US; en',
                   'iPad; CPU iPhone OS 15_4 like Mac OS X']
    }

    # Check if the user agent contains any of the common desktop user agents
    for agent in user_agents['desktop']:
        if re.search(agent, user_agent, re.IGNORECASE):
            return 'desktop'

    # Check if the user agent contains any of the common mobile user agents
    for agent in user_agents['mobile']:
        if re.search(agent, user_agent, re.IGNORECASE):
            return 'mobile'

    # If no match is found, return 'unknown'
    return 'unknown'

def get_device_type(user_agent):
    # Use regular expressions to detect the browser type
    browser_types = {
        'Chrome': ['Chrome/', 'CriOS'],
        'Firefox': ['Firefox/', 'Gecko'],
        'Safari': ['Safari/', 'AppleWebKit'],
        'Edge': ['Edge/', 'Edg/'],
        'Opera': ['Opera/', 'OPR/']
    }

    # Detect the browser type
    for browser, patterns in browser_types.items():
        for pattern in patterns:
            if re.search(pattern, user_agent, re.IGNORECASE):
                return browser

    # If no match is found, return 'unknown'
    return 'unknown'

def get_device_fingerprint(user_agent):
    # Combine the device type and device type to generate a unique fingerprint
    device_fingerprint = f"{get_device_type(user_agent)}_{get_user_agent(user_agent)}"
    return device_fingerprint

def detect_device(user_agent):
    # Get the device fingerprint
    device_fingerprint = get_device_fingerprint(user_agent)

    # Make a request to a remote server to verify the device fingerprint
    try:
        response = requests.get(f'http://example.com/verify/{device_fingerprint}', timeout=5)
        if response.status_code == 200:
            return device_fingerprint
        else:
            return 'unknown'
    except requests.exceptions.RequestException:
        return 'unknown'

# Example usage
user_agent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/74.0.3729.169 Safari/537.3'
