import globus
from globus import errors
from globus.storageclient import StorageClient
from globus.storageclient.exceptions import NotFound
from globus.storageclient.exceptions import Forbidden
import os
import shutil

def upload_file(storage_url, bucket, file_path, file_name):
    try:
        storage_client = StorageClient(storage_url=storage_url)
        with open(file_path, 'rb') as file:
            response = storage_client.upload_file(file, bucket, file_name)
        print(f"File {file_name} uploaded successfully")
    except errors.GlobusAPIError as e:
        print(f"Error uploading file: {e}")
    except FileNotFoundError:
        print("File not found")
    except Exception as e:
        print(f"An error occurred: {e}")

def download_file(storage_url, bucket, file_path, file_name):
    try:
        storage_client = StorageClient(storage_url=storage_url)
        response = storage_client.get_file(bucket, file_name, dest_path=file_path)
        print(f"File {file_name} downloaded successfully")
    except NotFound:
        print(f"File {file_name} not found")
    except Forbidden:
        print(f"Permission denied to download file {file_name}")
    except errors.GlobusAPIError as e:
        print(f"Error downloading file: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

def create_directory(storage_url, bucket, dir_path):
    try:
        storage_client = StorageClient(storage_url=storage_url)
        response = storage_client.create_directory(bucket, dir_path)
        print(f"Directory {dir_path} created successfully")
    except errors.GlobusAPIError as e:
        print(f"Error creating directory: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

def delete_directory(storage_url, bucket, dir_path):
    try:
        storage_client = StorageClient(storage_url=storage_url)
        response = storage_client.delete_directory(bucket, dir_path)
        print(f"Directory {dir_path} deleted successfully")
    except NotFound:
        print(f"Directory {dir_path} not found")
    except Forbidden:
        print(f"Permission denied to delete directory {dir_path}")
    except errors.GlobusAPIError as e:
        print(f"Error deleting directory: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

def transfer_file(storage_url, src_bucket, src_file, dst_bucket, dst_file):
    try:
        storage_client = StorageClient(storage_url=storage_url)
        response = storage_client.copy_file(src_bucket, src_file, dst_bucket, dst_file)
        print(f"File {src_file} transferred successfully to {dst_file}")
    except errors.GlobusAPIError as e:
        print(f"Error transferring file: {e}")
