import os

class Version:
    def __init__(self, version, commit_message, branch):
        self.version = version
        self.commit_message = commit_message
        self.branch = branch

class Project:
    def __init__(self, name):
        self.name = name
        self.versions = []
        self.branches = {}
        self.tags = set()

    def add_version(self, version):
        self.versions.append(version)

    def create_branch(self, branch):
        self.branches[branch] = self.versions.copy()

    def tag_version(self, version):
        self.tags.add(version.version)

class GitRepository:
    def __init__(self, project):
        self.project = project

    def create_version(self, version):
        new_version = Version(version, f"Initial version {version}", "main")
        self.project.add_version(new_version)
        self.project.create_branch("main")
        self.project.create_branch(f"feature-{version}")

    def create_branch_from_version(self, version):
        branch = f"feature-{version}"
        if branch not in self.project.branches:
            self.project.create_branch(branch)
            self.project.create_branch("main")

    def tag_version(self, version):
        if version in self.project.versions:
            self.project.tags.add(version.version)

    def checkout_branch(self, branch):
        if branch in self.project.branches:
            return self.project.branches[branch]
        else:
            return None

def main():
    project = Project("My Project")
    git_repo = GitRepository(project)

    # Create initial version
    git_repo.create_version(1)

    # Create branch from initial version
    git_repo.create_branch_from_version(1)

    # Checkout initial branch
    versions = git_repo.checkout_branch("main")
    print(versions)

    # Create new version
    git_repo.create_version(2)

    # Checkout new branch
    versions = git_repo.checkout_branch("feature-2")
    print(versions)

    # Tag new version
    git_repo.tag_version(versions[0])

if __name__ == "__main__":
