import collections
import torch

class RecordSequentialStorage:
    def __init__(self, max_size):
        self.max_size = max_size
        self.queue = collections.deque(maxlen=max_size)

    def add_record(self, input_data, label):
        self.queue.append((input_data, label))

    def retrieve_records(self, batch_size):
        batch = []
        for i in range(min(batch_size, len(self.queue))):
            input_data, label = self.queue.popleft()
            batch.append((input_data, label))
        return batch

    def get_length(self):
        return len(self.queue)

    def clear_queue(self):
        self.queue.clear()

# Example usage
storage = RecordSequentialStorage(max_size=100)
storage.add_record(input_data=torch.randn(1, 10), label=torch.tensor([0]))
storage.add_record(input_data=torch.randn(1, 10), label=torch.tensor([1]))

batch = storage.retrieve_records(batch_size=2)
for input_data, label in batch:
    print(input_data, label)
```

This code implements a simple record sequential storage system using a FIFO queue to store and retrieve data in a sequence of records. The `RecordSequentialStorage` class takes a maximum size as an argument and uses a `collections.deque` to store the records. The `add_record` method adds a new record to the queue, the `retrieve_records` method retrieves a batch of records from the queue, and the `get_length` and `clear_queue` methods provide additional utility functions. The example usage demonstrates how to create an instance of the class, add records, retrieve a batch of records, and print the input data and labels.

