import jax.numpy as jnp
from jax.experimental import stax

# Define a normal distribution
normal_dist = stax.Normal(loc=0.0, scale=1.0)

# Compute probabilities for a normal distribution
def compute_normal_probabilities(dist, x):
    return jnp.exp(-0.5 * (x - dist.loc)**2 / dist.scale**2) / (dist.scale * jnp.sqrt(2 * jnp.pi))

# Compute cumulative probabilities for a normal distribution
def compute_normal_cdf(dist, x):
    return compute_normal_probabilities(dist, x) / compute_normal_probabilities(dist, dist.loc + dist.scale)

# Generate samples from a normal distribution
def generate_normal_samples(dist, shape):
    return dist.sample(shape=shape)

# Define a uniform distribution
uniform_dist = stax.Uniform(low=-1.0, high=1.0)

# Compute probabilities for a uniform distribution
def compute_uniform_probabilities(dist, x):
    return jnp.where(x < dist.low, 0, x - dist.low) / (dist.high - dist.low)

# Compute cumulative probabilities for a uniform distribution
def compute_uniform_cdf(dist, x):
    return jnp.where(x < dist.low, 0, x - dist.low) / (dist.high - dist.low)

# Generate samples from a uniform distribution
def generate_uniform_samples(dist, shape):
    return dist.sample(shape=shape)

# Define a normal distribution with a different scale
normal_dist_scale2 = stax.Normal(loc=0.0, scale=2.0)

# Compute probabilities for the second normal distribution
def compute_normal_probabilities_scale2(dist, x):
    return jnp.exp(-0.5 * (x - dist.loc)**2 / dist.scale**2) / (dist.scale * jnp.sqrt(2 * jnp.pi))

# Compute cumulative probabilities for the second normal distribution
def compute_normal_cdf_scale2(dist, x):
    return compute_normal_probabilities_scale2(dist, x) / compute_normal_probabilities_scale2(dist, dist.loc + dist.scale)

# Generate samples from the second normal distribution
def generate_normal_samples_scale2(dist, shape):
    return dist.sample(shape=shape)
