class Pagination:
    def __init__(self, total_records, records_per_page):
        self.total_records = total_records
        self.records_per_page = records_per_page
        self.current_page = 1

    def get_records(self, page=1):
        start_index = (page - 1) * self.records_per_page
        end_index = start_index + self.records_per_page
        return self.total_records[start_index:end_index]

    def get_total_pages(self):
        return -(-self.total_records // self.records_per_page)

    def get_current_page_number(self):
        return self.current_page

    def increment_page(self):
        self.current_page += 1


class PaginationExample:
    def __init__(self, data):
        self.data = data
        self.pagination = Pagination(len(data), 10)

    def display_records(self):
        page_number = self.pagination.get_current_page_number()
        records = self.pagination.get_records(page_number)
        print(f"Page {page_number} of {self.pagination.get_total_pages()}")
        for record in records:
            print(record)

    def navigate_pages(self):
        while True:
            action = input("Enter 'n' to navigate to next page, 'p' to navigate to previous page, or 'q' to quit: ")
            if action == 'n':
                self.pagination.increment_page()
                self.display_records()
            elif action == 'p':
                if self.pagination.get_current_page_number() > 1:
                    self.pagination.increment_page()
                    self.display_records()
                else:
