from fuzzywuzzy import fuzz
from fuzzywuzzy import process

class FuzzySet:
    def __init__(self, name, membership_function):
        self.name = name
        self.membership_function = membership_function

    def fuzzify(self, input_value):
        return self.membership_function(input_value)

    def infer(self, input_value, other_set):
        # This method is not implemented as it requires a specific inference rule.
        # For example, in Mamdani type fuzzy inference, the output is calculated as:
        # output = max( (a * b) / (a + b - 1) for a in self.membership_function, b in other_set.membership_function )
        # In this case, we will just return the maximum membership value of the input value in both sets.
        return max(self.membership_function.get(input_value, 0), other_set.membership_function.get(input_value, 0))

    def defuzzify(self, input_value):
        # This method is not implemented as it requires a specific defuzzification method.
        # For example, in centroid defuzzification, the output is calculated as:
        # output = sum( (x * m(x)) for x in self.membership_function.keys() ) / sum( m(x) for x in self.membership_function.keys() )
        # In this case, we will just return the weighted average of the input value and the closest membership value.
        closest_membership_value = min(self.membership_function.keys(), key=lambda x: abs(x - input_value))
        return (input_value * self.membership_function[closest_membership_value] + closest_membership_value * self.membership_function.get(closest_membership_value + 1, 0)) / (self.membership_function[closest_membership_value] + self.membership_function.get(closest_membership_value + 1, 0))
