import os
import configparser
import json

class ProgramSettings:
    def __init__(self, config_file=None, env_variables=None):
        self.config_file = config_file
        self.env_variables = env_variables

    def load_config(self):
        config = configparser.ConfigParser()
        if self.config_file:
            config.read(self.config_file)
        else:
            # Use environment variables if no config file is provided
            env_vars = {}
            for var in self.env_variables:
                env_vars[var] = os.environ.get(var)
            config.read_dict(env_vars)

        return config

    def load_env_variables(self):
        env_vars = {}
        for var in self.env_variables:
            env_vars[var] = os.environ.get(var)
        return env_vars

    def get_setting(self, section, key):
        config = self.load_config()
        env_vars = self.load_env_variables()
        setting = config.get(section, key)
        if setting:
            return setting
        else:
            for var in self.env_variables:
                setting = os.environ.get(f"{var}_{key}")
                if setting:
                    return setting
        return None

# Example usage:
if __name__ == "__main__":
    env_variables = ["DB_HOST", "DB_PORT", "DB_NAME"]
    settings = ProgramSettings(config_file="config.ini", env_variables=env_variables)

