def sum_of_pairs(nums, target):
    pairs = set()
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] == target:
                pairs.add((min(nums[i], nums[j]), max(nums[i], nums[j])))
    return sum(pair[1] - pair[0] for pair in pairs)

def longest_common_substring(strings):
    def lcs(s1, s2):
        m, n = len(s1), len(s2)
        dp = [[0] * (n+1) for _ in range(m+1)]
        max_len = 0
        end = 0
        for i in range(1, m+1):
            for j in range(1, n+1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                    if dp[i][j] > max_len:
                        max_len = dp[i][j]
                        end = i
                else:
                    dp[i][j] = 0
        return s1[end-max_len:end]

    return [lcs(s1, s2) for s1 in strings for s2 in strings if s1 != s2]

from itertools import combinations
from collections import defaultdict

def unique_permutations(nums, k):
    count = defaultdict(int)
    for perm in permutations(nums, k):
        count[tuple(perm)] += 1
    return sum(count.values())

def split_into_subsets(strings):
    min_diff = float('inf')
    best_split = None
    for i in range(len(strings)):
        left_sum = sum(strings[:i])
        right_sum = sum(strings[i:])
        diff = abs(left_sum - right_sum)
        if diff < min_diff:
            min_diff = diff
            best_split = (left_sum, right_sum)
    return best_split

from itertools import chain, combinations

def closest_sum(nums, target):
    sums = sorted(set(chain(*map(lambda x: combinations(nums, x), range(0, len(nums)+1)))))
    min_diff = float('inf')
    closest_sum = None
    for s in sums:
        diff = abs(target - s)
        if diff < min_diff:
            min_diff = diff
            closest_sum = s
    return closest_sum

def longest_common_substring_two_strings(s1, s2):
    lcs = []
    i, j = 0, 0
    while i < len(s1) and j < len(s2):
        if s1[i] == s2[j]:
            lcs.append(s1[i])
            i += 1
            j += 1
        elif j > i:
            j = j - j + i
        else:
            i += 1
    return ''.join(lcs)

def longest_common_substring(list_of_strings):
    return [longest_common_substring_two_strings(s1, s2) for s1 in list_of_strings for s2 in list_of_strings if s1 != s2]

