from pycuda.compiler import SourceModule

# Define the CUDA kernel function
kernel_source = """
__global__ void matmul_kernel(float *A, float *B, float *C, int rowsA, int colsA, int colsB) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < rowsA && col < colsB) {
        float sum = 0.0f;
        for (int i = 0; i < colsA; i++) {
            sum += A[row * colsA + i] * B[i * colsB + col];
        }
        C[row * colsB + col] = sum;
    }
}
"""

# Create the CUDA module from the kernel source
mod = SourceModule(kernel_source)

# Get the kernel function from the module
matmul_kernel = mod.get_function("matmul_kernel")

# Example usage:
