import itertools

class FancyIterable:
    def __init__(self, iterable, chunk_size):
        self.iterable = iterable
        self.chunk_size = chunk_size

    def __getitem__(self, idx):
        start = idx * self.chunk_size
        end = (idx + 1) * self.chunk_size
        if end > len(self.iterable):
            end = len(self.iterable)
        return itertools.islice(self.iterable, start, end)

    def __iter__(self):
        return self

def lazy_load(iterable, chunk_size):
    return FancyIterable(iterable, chunk_size)

