def dependency_decorator(func: Callable) -> Callable:
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # Store the dependency information in a dictionary
        graph[func.__name__] = {arg: arg for arg in args} + {**kwargs}
        return func(*args, **kwargs)
    return wrapper

# Initialize an empty graph
graph: Dict[str, Dict[str, str]] = {}

