import json
import os
import multiprocessing
import queue
from abc import ABC, abstractmethod
from typing import Dict, List, Callable

# Configuration class for task queue system
class Config:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config = self.load_config()

    def load_config(self) -> Dict:
        if not os.path.exists(self.config_file):
            raise FileNotFoundError(f"Configuration file {self.config_file} not found.")

        with open(self.config_file, 'r') as f:
            return json.load(f)

    def get_queues(self) -> Dict:
        return self.config.get('queues', {})

    def get_workers(self) -> Dict:
        return self.config.get('workers', {})

# Abstract base class for tasks
class Task(ABC):
    @abstractmethod
    def execute(self):
        pass

# Custom task class
class MyTask(Task):
    def __init__(self, data: str):
        self.data = data

    def execute(self):
        print(f"Executing task with data: {self.data}")

# Queue class
class Queue:
    def __init__(self, name: str):
        self.name = name
        self.queue = multiprocessing.Queue()

    def put(self, task: Task):
        self.queue.put(task)

    def get(self):
        return self.queue.get()

# Worker class
class Worker:
    def __init__(self, queue: Queue, worker_id: str):
        self.queue = queue
        self.worker_id = worker_id

    def run(self):
        while True:
            task = self.queue.get()
            if task is None:
                break
            task.execute()
            self.queue.task_done()

# Main function
def main():
    config_file = 'config.json'
    config = Config(config_file)
    queues = config.get_queues()
    workers = config.get_workers()

    # Create queues and workers
    queue_pool = {}
    for queue_name, queue_config in queues.items():
        queue_pool[queue_name] = Queue(queue_name)
        for worker_id, worker_config in queue_config.get('workers', {}).items():
            worker_pool = multiprocessing.Pool()
            worker = Worker(queue_pool[queue_name], worker_id)
            worker_pool.apply_async(worker.run)
            worker_pool.close()
            worker_pool.join()

    # Create custom tasks
    task1 = MyTask('Task 1 data')
    task2 = MyTask('Task 2 data')

    # Put tasks in queues
    for queue_name, queue in queue_pool.items():
        queue.put(task1)
        queue.put(task2)

    # Wait for all tasks to be processed
    for queue in queue_pool.values():
        queue.join()

if __name__ == "__main__":
    main()
```

This code defines a task queue system with extensibility for custom tasks, queues, and worker pools. It uses a configuration file to specify the task-queue architecture and runs on a distributed cluster for data science workflows. The system consists of the following components:

1.  `Config` class: Loads the task queue configuration from a JSON file and provides methods to retrieve queues and workers.
2.  `Task` abstract base class: Defines the interface for tasks, which can be executed by workers.
3.  `MyTask` custom task class: Demonstrates how to create a custom task with data.
4.  `Queue` class: Manages a queue of tasks and provides methods to put and get tasks.
5.  `Worker` class: Runs tasks in a worker pool and provides a method to run indefinitely until stopped.

To use this code, create a `config.json` file with the following structure:

```json
{
    "queues": {
        "queue1": {
            "workers": {
                "worker1": {
                    "num_workers": 1
                },
                "worker2": {
                    "num_workers": 1
                }
            }
        },
        "queue2": {
            "workers": {
                "worker3": {
                    "num_workers": 1
                }
            }
        }
    }
}
```

Replace the `num_workers` values with the desired number of workers for each queue.

The `main` function demonstrates how to create queues, workers, custom tasks, and put tasks in queues. It also shows how to wait for all tasks to be processed by joining each queue.

