import gitpython

class GitIgnoreParser:
    def __init__(self, repository_path):
        self.repository = gitpython.Repo(repository_path)

    def parse_gitignore(self):
        ignore_file = self.repository.git.config.get('core', 'ignores')
        if not ignore_file:
            return []

        ignored_patterns = []
        for line in ignore_file.splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            ignored_patterns.append(line)

        return ignored_patterns


# Usage
if __name__ == "__main__":
    repository_path = '/path/to/your/repo'
    parser = GitIgnoreParser(repository_path)
    ignored_patterns = parser.parse_gitignore()
    print(ignored_patterns)
