class DVDPlayer:
    def __init__(self):
        self.is_playing = False
        self.dvd_title = ""

    def play_dvd(self, title):
        self.is_playing = True
        self.dvd_title = title
        print(f"Playing DVD: {title}")

    def stop_playback(self):
        self.is_playing = False
        self.dvd_title = ""
        print("Playback stopped.")

    def pause_playback(self):
        if self.is_playing:
            print("Playback paused.")
        else:
            print("Playback is not playing.")

    def resume_playback(self):
        if not self.is_playing:
            print("Playback resumed.")
        else:
            print("Playback is already playing.")

    def eject_dvd(self):
        print("DVD ejected.")

    def insert_dvd(self, title):
        print(f"Inserting DVD: {title}")


def main():
    dvd_player = DVDPlayer()

    while True:
        print("\nDVD Player Interface")
        print("1. Play DVD")
        print("2. Stop Playback")
        print("3. Pause Playback")
        print("4. Resume Playback")
        print("5. Eject DVD")
        print("6. Insert DVD")
        print("7. Quit")

        choice = input("Choose an option: ")

        if choice == "1":
            dvd_title = input("Enter DVD title: ")
            dvd_player.play_dvd(dvd_title)
        elif choice == "2":
            dvd_player.stop_playback()
        elif choice == "3":
            dvd_player.pause_playback()
        elif choice == "4":
            dvd_player.resume_playback()
        elif choice == "5":
            dvd_player.eject_dvd()
        elif choice == "6":
            dvd_title = input("Enter DVD title: ")
            dvd_player.insert_dvd(dvd_title)
        elif choice == "7":
            break
        else:
            print("Invalid choice. Please choose a valid option.")


if __name__ == "__main__":
    main()
