def parse_csv_string(csv_string):
    """Parse a string representation of a CSV table into a dictionary."""
    rows = []
    for row in csv_string.split('\n'):
        if row:  # skip empty lines
            rows.append(dict(zip(row.split(','), range(len(row.split(','))))))
    return rows

def parse_json_string(json_string):
    """Parse a string representation of a JSON table into a dictionary."""
    return json.loads(json_string)

