import ast
import os

def extract_imports(file_path):
    with open(file_path, 'r') as file:
        code = file.read()

    tree = ast.parse(code)

    imports = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.name
                module_path = alias.asname or node.module
                imports.append((name, module_path))
        elif isinstance(node, ast.ImportFrom):
            name = node.module
            module_path = node.module
            imports.append((name, module_path))

    return imports

def print_imports(imports):
    for name, module_path in imports:
        print(f"{name} (from {module_path})")

def main():
    file_path = 'path_to_your_python_file.py'  # replace with your file path
    imports = extract_imports(file_path)
    print_imports(imports)

if __name__ == "__main__":
    main()
