import flake8
from flake8 import base

class ReadabilityChecker(base.Checker):
    """Extends flake8 to check variable names for readability."""

    def __init__(self, config):
        super().__init__(config)

    @base.checker
    def check_variable_name(self, node):
        """Checks if variable names are clear and easy to understand."""

        if isinstance(node.value, str):
            # Check if variable name is a single word
            if len(node.value.split()) > 1:
                # Suggest improvement if variable name is unclear or confusing
                yield base.NodeError(
                    "Variable name '{node.value}' is unclear or confusing. "
                    "Consider using a more descriptive name.".format(node=node)
                )

def main():
    # Initialize flake8 with our custom checker
    config = base.Config(extend=True)
    config.add_checker(ReadabilityChecker(config))

    # Run flake8 with the custom configuration
    flake8.main([__file__, "-"])

if __name__ == "__main__":
    main()
