import pytest
from pytest_run import RunSession

class BatchRunner:
    def __init__(self, max_batch_size):
        self.max_batch_size = max_batch_size
        self.batch = []

    def add_test(self, test):
        self.batch.append(test)
        if len(self.batch) >= self.max_batch_size:
            yield from self.run_batch()
            self.batch = []

    def run_batch(self):
        yield from self._run_batch()

    def _run_batch(self):
        session = RunSession(self.batch)
        yield from session.run()

def pytest_addoption(parser):
    parser.addoption("--batch-size", action="store", default=10, help="Maximum number of tests to run in each batch")

def pytest_configure(config):
    config.addinivalue_line("batch_size", "10")

def pytest_sessionstart(session):
    session.addhook(BatchRunner(session.config.get("batch_size")))
