import os
import json
from datetime import datetime

class Experiment:
    def __init__(self, name, description, params, results):
        self.name = name
        self.description = description
        self.params = params
        self.results = results
        self.date = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

class ExperimentManager:
    def __init__(self):
        self.experiments = {}

    def add_experiment(self, experiment):
        self.experiments[experiment.name] = experiment

    def search_experiments(self, keyword):
        return [experiment for experiment in self.experiments.values() if keyword in experiment.name or keyword in experiment.description]

    def compare_experiments(self, params):
        matching_experiments = [experiment for experiment in self.experiments.values() if all(param in experiment.params for param in params)]
        return matching_experiments

    def save_experiments(self, filename):
        data = []
        for experiment in self.experiments.values():
            data.append({
                "name": experiment.name,
                "description": experiment.description,
                "params": experiment.params,
                "results": experiment.results,
                "date": experiment.date
            })
        with open(filename, 'w') as f:
            json.dump(data, f, indent=4)

    def load_experiments(self, filename):
        try:
            with open(filename, 'r') as f:
                data = json.load(f)
                for experiment_data in data:
                    self.add_experiment(Experiment(experiment_data['name'], experiment_data['description'], experiment_data['params'], experiment_data['results']))
        except FileNotFoundError:
            print("File not found")

def main():
    manager = ExperimentManager()
    while True:
        print("1. Add experiment")
        print("2. Search experiments")
        print("3. Compare experiments")
        print("4. Save experiments")
        print("5. Load experiments")
        print("6. Exit")
        choice = input("Choose an option: ")
        if choice == "1":
            name = input("Enter experiment name: ")
            description = input("Enter experiment description: ")
            params = input("Enter experiment parameters (comma separated): ").split(',')
            params = [param.strip() for param in params]
            results = input("Enter experiment results (comma separated): ").split(',')
            results = [result.strip() for result in results]
            manager.add_experiment(Experiment(name, description, params, results))
        elif choice == "2":
            keyword = input("Enter search keyword: ")
            results = manager.search_experiments(keyword)
            for experiment in results:
                print(f"Name: {experiment.name}, Description: {experiment.description}, Date: {experiment.date}")
        elif choice == "3":
            params = input("Enter comparison parameters (comma separated): ").split(',')
            params = [param.strip() for param in params]
            results = manager.compare_experiments(params)
            for experiment in results:
                print(f"Name: {experiment.name}, Description: {experiment.description}, Date: {experiment.date}")
        elif choice == "4":
            filename = input("Enter filename: ")
            manager.save_experiments(filename)
        elif choice == "5":
            filename = input("Enter filename: ")
            manager.load_experiments(filename)
        elif choice == "6":
            break
        else:
            print("Invalid choice")

if __name__ == "__main__":
    main()
```

This code provides a basic framework for recording, searching, and comparing AI experiments. It uses two classes: `Experiment` to represent individual experiments and `ExperimentManager` to manage a collection of experiments. The `ExperimentManager` class provides methods to add, search, compare, save, and load experiments. The `main` function provides a simple command-line interface to interact with the `ExperimentManager`.

