class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.count = 1


class AVLTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        self.root = self._insert(self.root, key)

    def _insert(self, node, key):
        if not node:
            return Node(key)
        if key < node.key:
            node.left = self._insert(node.left, key)
        else:
            node.right = self._insert(node.right, key)

        # Update height
        node.count = 1 + self._get_height(node.left) + self._get_height(node.right)

        # Balance the tree
        balance_factor = self._get_balance_factor(node)
        if balance_factor > 1:
            if key < node.left.key:
                return self._right_rotate(node)
            else:
                node.left = self._left_rotate(node.left)
                return self._right_rotate(node)
        elif balance_factor < -1:
            if key > node.right.key:
                return self._left_rotate(node)
            else:
                node.right = self._right_rotate(node.right)
                return self._left_rotate(node)

        return node

    def delete(self, key):
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if not node:
            return node
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            if not node.left and not node.right:
                return None
            elif not node.left:
                return node.right
            elif not node.right:
                return node.left
            else:
                min_node = self._find_min(node.right)
                node.key = min_node.key
                node.right = self._delete(node.right, min_node.key)

        # Update height
        if node:
            node.count = 1 + self._get_height(node.left) + self._get_height(node.right)

        # Balance the tree
        balance_factor = self._get_balance_factor(node)
        if balance_factor > 1:
            if self._get_balance_factor(node.left) >= 0:
                return self._right_rotate(node)
            else:
                node.left = self._left_rotate(node.left)
                return self._right_rotate(node)
        elif balance_factor < -1:
            if self._get_balance_factor(node.right) <= 0:
                return self._left_rotate(node)
            else:
                node.right = self._right_rotate(node.right)
                return self._left_rotate(node)

        return node

    def _left_rotate(self, node):
        temp = node.right
        node.right = temp.left
        temp.left = node

        # Update height
        node.count = 1 + self._get_height(node.left) + self._get_height(node.right)
        temp.count = 1 + self._get_height(temp.left) + self._get_height(temp.right)

        return temp

    def _right_rotate(self, node):
        temp = node.left
        node.left = temp.right
        temp.right = node

        # Update height
        node.count = 1 + self._get_height(node.left) + self._get_height(node.right)
        temp.count = 1 + self._get_height(temp.left) + self._get_height(temp.right)

        return temp

    def _get_height(self, node):
        if not node:
            return 0
        return node.count

    def _get_balance_factor(self, node):
        if not node:
            return 0
        return self._get_height(node.left) - self._get_height(node.right)

    def _find_min(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def query(self, key):
        return self._query(self.root, key)

    def _query(self, node, key):
        if not node:
            return None
        if key < node.key:
            return self._query(node.left, key)
        elif key > node.key:
            return self._query(node.right, key)
        else:
            return node.key
