import threading
import signal
import sys
import inspect
import traceback
import time
import re
from collections import defaultdict
from contextlib import contextmanager

class ThreadSafeDict(defaultdict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.lock = threading.Lock()

    def __setitem__(self, key, value):
        with self.lock:
            super().__setitem__(key, value)

    def __getitem__(self, key):
        with self.lock:
            return super().__getitem__(key)

class Pdb:
    def __init__(self):
        self.frames = {}
        self._stop_event = threading.Event()
        self._stop_handler = None

    def start(self):
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGQUIT, self._handle_signal)

    def _handle_signal(self, sig, frame):
        self._stop_event.set()
        if self._stop_handler:
            self._stop_handler()

    def _stop(self):
        if self._stop_handler:
            self._stop_handler()
        self._stop_event.set()

    def set_stop_handler(self, handler):
        self._stop_handler = handler

    def set_trace(self, frame):
        self.frames[frame] = True
        self._stop_event.clear()

    def get_frames(self):
        return list(self.frames.keys())

    def get_current_frame(self):
        if not self.frames:
            return None
        current_frame = inspect.currentframe().f_back
        while current_frame:
            if current_frame in self.frames:
                return current_frame
            current_frame = current_frame.f_back
        return None

    def next(self):
        frame = self.get_current_frame()
        if frame:
            self.frames[frame] = False
            return frame
        return None

    def step_over(self):
        frame = self.get_current_frame()
        if frame:
            self.frames[frame] = False
            return frame
        return None

    def step_into(self):
        frame = self.get_current_frame()
        if frame:
            self.frames[frame] = False
            return frame
        return None

    def step_out(self):
        frame = self.get_current_frame()
        if frame:
            self.frames[frame] = True
            return frame
        return None

    def cont(self):
        if self._stop_event.is_set():
            raise KeyboardInterrupt
        return True

    def runcall(self, func, *args, **kwargs):
        frame = self.get_current_frame()
        if frame:
            self.frames[frame] = False
            return func(*args, **kwargs)
        return None

    def runcall_and_return(self, func, *args, **kwargs):
        frame = self.get_current_frame()
        if frame:
            self.frames[frame] = False
            return func(*args, **kwargs)
        return None

    def get_stack_trace(self):
        stack_trace = []
        current_frame = inspect.currentframe().f_back
        while current_frame:
            frame = inspect.currentframe().f_back
            stack_trace.append(traceback.extract_stack(frame))
            current_frame = current_frame.f_back
        return stack_trace

    def run_in_thread(self, func, *args, **kwargs):
        thread = threading.Thread(target=self._run_in_thread, args=(func, *args, **kwargs))
        thread.start()
        thread.join()
        return thread

    def _run_in_thread(self, func, *args, **kwargs):
        try:
            func(*args, **kwargs)
        except Exception as e:
            print(e)

class Pdbpp(Pdb):
    def __init__(self):
        super().__init__()
        self._thread_safe_dict = ThreadSafeDict()

    def add_command(self, command):
        command_name, command_func = command.split()
        command_func = getattr(self, command_name)
        self._thread_safe_dict[command_func] = command_func

    def run_command(self, command):
        command_name, *args = command.split()
        command_func = self._thread_safe_dict.get(command_name)
        if command_func:
            return command_func(*args)
        return None

    def list_commands(self):
        return list(self._thread_safe_dict.keys())

    def help_command(self, command):
        return f"Help for {command}"

    def set_trace(self, frame):
        super().set_trace(frame)
        self._thread_safe_dict[self.set_trace] = self.set_trace

    def get_frames(self):
        super().get_frames()

    def get_current_frame(self):
        super().get_current_frame()

    def next(self):
        super().next()

    def step_over(self):
        super().step_over()

    def step_into(self):
        super().step_into()

    def step_out(self):
        super().step_out()

    def cont(self):
        super().cont()

    def runcall(self, func, *args, **kwargs):
        super().runcall(func, *args, **kwargs)

    def runcall_and_return(self, func, *args, **kwargs):
        super().runcall_and_return(func, *args, **kwargs)

    def get_stack_trace(self):
        super().get_stack_trace()

    def run_in_thread(self, func, *args, **kwargs):
        super().run_in_thread(func, *args, **kwargs)

    def _run_in_thread(self, func, *args, **kwargs):
        super()._run_in_thread(func, *args, **kwargs)
```

