import json
import re

class JSONSchema:
    def __init__(self, type, title, description):
        self.type = type
        self.title = title
        self.description = description
        self.properties = {}
        self.required = []
        self.format = {}

    def add_property(self, name, schema):
        self.properties[name] = schema

    def add_required(self, name):
        self.required.append(name)

    def add_format(self, name, format):
        self.format[name] = format

    def validate(self, data):
        for name in self.required:
            if name not in data:
                return False
        if self.type == 'object':
            for prop in self.properties:
                if not self.properties[prop].validate(data[prop]):
                    return False
        elif self.type == 'array':
            for item in data:
                if not self.properties.get('items', None).validate(item):
                    return False
        elif self.type == 'string':
            if not re.match(self.properties.get('format', '^[^\\s]+$'), data):
                return False
        elif self.type == 'number':
            if not re.match(self.properties.get('format', '^-?\\d+(\\.\\d+)?$'), data):
                return False
        elif self.type == 'boolean':
            if data.lower() not in ['true', 'false']:
                return False
        return True

    def format(self, data):
        formatted_data = {}
        for name in self.required:
            formatted_data[name] = data[name]
        if self.type == 'object':
            for prop in self.properties:
                formatted_data[prop] = self.properties[prop].format(data[prop])
        elif self.type == 'array':
            formatted_data['items'] = self.properties['items'].format(data)
        elif self.type == 'string':
            formatted_data['format'] = self.properties['format']
        elif self.type == 'number':
            formatted_data['format'] = self.properties['format']
        elif self.type == 'boolean':
            formatted_data['format'] = self.properties['format']
        return formatted_data

# Example usage
schema = JSONSchema('object', 'User', 'User information')
schema.add_property('name', JSONSchema('string', '', 'User name'))
schema.add_property('email', JSONSchema('string', '', 'User email'))
schema.add_required(['name', 'email'])
schema.add_format('email', '^[^@]+@[^@]+\.[^@]+$')

data = {'name': 'John Doe', 'email': 'johndoe@example.com'}
if schema.validate(data):
    formatted_data = schema.format(data)
    print(json.dumps(formatted_data, indent=4))
else:
    print("Invalid data")
