import yaml

class NestedFileInstantiator(yaml.Constructors.SingleFileInstantiator):
    def _construct_yaml_node(self, constructor, node):
        if node.start_mark:
            file_path = node.start_mark.value
            with open(file_path, 'r') as f:
                inner_yaml = yaml.safe_load(f)
                return self._construct_yaml_node(constructor, inner_yaml)
        else:
            return super()._construct_yaml_node(constructor, node)

