import cssutils
import re

def minify_css(css_code):
    # Parse the CSS code into a CSSStyleSheet object
    sheet = cssutils.parseString(css_code)

    # Get the rules from the stylesheet
    rules = sheet.cssRules

    # Initialize an empty list to store the beautified rules
    beautified_rules = []

    # Iterate over each rule in the stylesheet
    for rule in rules:
        # Check if the rule is a style rule
        if rule.type == cssutils.css.CSSStyleRule:
            # Get the style declaration from the rule
            style = rule.style

            # Initialize an empty dictionary to store the style declarations
            style_declarations = {}

            # Iterate over each property in the style declaration
            for property in style:
                # Get the property name and value
                prop_name = property.name
                prop_value = property.value

                # Check if the property name is not an obscure selector
                if not re.search(r'^[#.]{1,4}[a-zA-Z0-9_-]+$', prop_name):
                    # Add the property to the style declarations dictionary
                    style_declarations[prop_name] = prop_value

            # Initialize an empty string to store the beautified style declaration
            beautified_style = ''

            # Iterate over each style declaration in the style declarations dictionary
            for prop_name, prop_value in style_declarations.items():
                # Add the property name and value to the beautified style declaration
                beautified_style += f'{prop_name}: {prop_value};\n'

            # Add the beautified style declaration to the beautified rules list
            beautified_rules.append(cssutils.css.CSSStyleRule(style=cssutils.css.CSSStyleDeclaration(beautified_style)))

    # Initialize an empty string to store the beautified CSS code
    beautified_css = ''

    # Iterate over each rule in the beautified rules list
    for rule in beautified_rules:
        # Add the rule to the beautified CSS code
        beautified_css += f'{rule.type} {{\n'

        # Iterate over each property in the rule style declaration
        for prop_name, prop_value in rule.style.cssText.split(';'):
            # Add the property name and value to the beautified CSS code
            beautified_css += f'  {prop_name}: {prop_value};\n'

        # Close the rule block
        beautified_css += '}'

    # Return the beautified CSS code
    return beautified_css

# Test the function
css_code = '''
