import cv2
import numpy as np

def load_image(image_path):
    """Loads an image from the specified path."""
    return cv2.imread(image_path)

def preprocess_image(image):
    """Preprocesses the input image by resizing and converting to grayscale."""
    resized_image = cv2.resize(image, (224, 224))
    return cv2.cvtColor(resized_image, cv2.COLOR_BGR2GRAY)

def detect_objects(image):
    """Detects objects in the input image using the Haar cascade classifier."""
    object_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    objects = object_cascade.detectMultiScale(gray_image, scaleFactor=1.1, minNeighbors=5)
    return objects

def detect_faces(image):
    """Detects faces in the input image using the Haar cascade classifier."""
    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray_image, scaleFactor=1.1, minNeighbors=5)
    return faces

def recognize_faces(image, known_faces):
    """Recognizes faces in the input image against a list of known faces."""
    face_locations = detect_faces(image)
    recognized_faces = []
    for (x, y, w, h) in face_locations:
        face_roi = image[y:y+h, x:x+w]
        face_encoding = cv2.face.face_encodings(face_roi)
        if face_encoding:
            for encoding in face_encoding:
                matches = cv2.compareFaces(encoding, known_faces, ftype=2)
                if matches > 0.6:
                    recognized_faces.append(known_faces[matches][0])
    return recognized_faces
