import ast
import io
import sys

class TypeHintComplexityChecker(ast.NodeVisitor):
    def __init__(self):
        self.type_hints = []
        self.complexity = 0

    def visit_FunctionDef(self, node):
        self.type_hints.append(node.args.args)
        self.complexity += len(node.args.args)
        self.generic_visit(node)

    def visit_ClassDef(self, node):
        self.type_hints.append(node.bases)
        self.complexity += len(node.bases)
        self.generic_visit(node)

    def report_complexity(self):
        if self.complexity == 0:
            return 0
        else:
            return self.complexity / len(self.type_hints)

class Flake8TypeHintComplexityChecker(ast.NodeVisitor):
    def __init__(self, filename):
        self.filename = filename
        self.type_hints = []
        self.complexity = 0
        self.reported_issues = set()

    def visit_FunctionDef(self, node):
        self.type_hints.append(node.args.args)
        self.complexity += len(node.args.args)
        self.generic_visit(node)

    def visit_ClassDef(self, node):
        self.type_hints.append(node.bases)
        self.complexity += len(node.bases)
        self.generic_visit(node)

    def report_complexity(self):
        if self.complexity == 0:
            return 0
        else:
            return self.complexity / len(self.type_hints)

    def report_issue(self, node, message):
        self.reported_issues.add(f"{self.filename}:{node.lineno}:{node.col_offset}: {message}")

def check_type_hints(source):
    try:
        tree = ast.parse(source)
    except SyntaxError as e:
        print(f"Syntax error: {e}")
        return

    checker = TypeHintComplexityChecker()
    checker.visit(tree)

    if checker.complexity == 0:
        print("No type hints found.")
    else:
        complexity = checker.report_complexity()
        print(f"Type hint complexity: {complexity:.2f}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python flake8_type_hint_complexity.py <source>")
        return

    filename = sys.argv[1]
    with io.open(filename, 'r', encoding='utf-8') as file:
        source = file.read()

    check_type_hints(source)

if __name__ == "__main__":
    main()
