from botocore.exceptions import ClientError

# Initialize Kinesis client
kinesis = boto3.client('kinesis')

# Create a stream
def create_stream(stream_name):
    try:
        response = kinesis.create_stream(
            StreamName=stream_name,
            ShardCount=1,
            StreamDescription={
                'ProductionAttributes': {
                    'KinesisStreamAggregationEnabled': 'true'
                }
            }
        )
        print(f"Stream {stream_name} created successfully")
    except ClientError as e:
        print(f"Failed to create stream {stream_name}: {e}")

# Put records into the stream
def put_records(stream_name, records):
    try:
        response = kinesis.put_records(
            StreamName=stream_name,
            Records=records,
            ShardIterator=None
        )
        print(f"Records put into stream {stream_name} successfully")
    except ClientError as e:
        print(f"Failed to put records into stream {stream_name}: {e}")

# Get shard iterator
def get_shard_iterator(stream_name):
    try:
        response = kinesis.describe_stream(
            StreamName=stream_name
        )
        return response['StreamDescription']['ShardIterator']
    except ClientError as e:
        print(f"Failed to get shard iterator for stream {stream_name}: {e}")

# Get records from a shard
def get_records(shard_iterator, records_to_get):
    try:
        response = kinesis.get_records(
            ShardIterator=shard_iterator,
            Limit=records_to_get,
            StartingPosition='TRIM_HORIZON'
        )
        return response['Records']
    except ClientError as e:
        print(f"Failed to get records from shard: {e}")

# Deaggregate records
def deaggregate_records(stream_name, records):
    shard_iterator = get_shard_iterator(stream_name)
    deaggregated_records = []
    while True:
        records = get_records(shard_iterator, 10)
        if not records:
            break
        deaggregated_records.extend(records)
        shard_iterator = records[-1]['ShardIterator']
    return deaggregated_records

# Aggregate records
def aggregate_records(stream_name):
    shard_iterator = get_shard_iterator(stream_name)
    aggregated_records = []
    while True:
        records = get_records(shard_iterator, 10)
        if not records:
            break
        aggregated_records.extend(records)
        shard_iterator = records[-1]['ShardIterator']
    return aggregated_records
