class AdvancedDoctestPlugin:
    @pytest_addoption
    def add_advanced_doctest_options(self, parser):
        parser.addoption("--advanced-doctest-run", action="store_true", default=False,
                         help="Run doctests in parallel")
        parser.addoption("--advanced-doctest-max-workers", type=int, default=multiprocessing.cpu_count(),
                         help="Maximum number of worker processes for running doctests in parallel")
        parser.addoption("--advanced-doctest-retries", type=int, default=3,
                         help="Number of retries for failing doctests")

    def pytest_runtest_setup(self, item: pytest.Item):
        if item.node.docstring:
            self.generate_test_cases(item.node.docstring)

    def pytest_runtest_makereport(self, item: pytest.Item, call: pytest.Call):
        if item.node.docstring:
            if item.outcome == pytest.OUTCOME_FAILED:
                self.report_failure(item, call, item.node.docstring)

    def generate_test_cases(self, docstring: str):
        docstring_parser.parse(docstring)

    def report_failure(self, item: pytest.Item, call: pytest.Call, docstring: str):
        print(f"Test failed: {item.node.name}")
        print(f"Docstring: {docstring}")
        print(f"Call: {call}")

def pytest_configure(config):
    config.addinivalue_line("advanced_doctest", "--advanced-doctest-run", action="store_true", default=False,
                            help="Run doctests in parallel")
    config.addinivalue_line("advanced_doctest", "--advanced-doctest-max-workers", type=int, default=multiprocessing.cpu_count(),
