class Iterable:
    def __init__(self, iterable):
        self.iterable = iter(iterable)

    def one(self):
        try:
            return next(self.iterable)
        except StopIteration:
            raise StopIteration

    def one_or_none(self):
        try:
            return next(self.iterable)
        except StopIteration:
            return None

    def many(self, k):
        for _ in range(k):
            try:
                next(self.iterable)
            except StopIteration:
                raise StopIteration
        return tuple(self.iterable)

    def skip(self, k):
        for _ in range(k):
            try:
                next(self.iterable)
            except StopIteration:
                raise StopIteration
        return next(self.iterable)

    def all(self):
        return all(self.iterable)


# Example usage:

class IterableExample(Iterable):
    def __init__(self, iterable):
        super().__init__(iterable)

iterable_example = IterableExample([True, False, True, True])

print(iterable_example.one())  # True
print(iterable_example.one_or_none())  # True
print(iterable_example.many(3))  # (True, False, True)
print(iterable_example.skip(2))  # True
print(iterable_example.all())  # True
