import boto3

def get_stacks(client, region_name):
    """Retrieve a list of all stacks in the specified region."""
    stacks = client.list_stacks(
        RegionName=region_name
    )
    return stacks['Stacks']

def get_stack_resources(client, stack_name, region_name):
    """Retrieve a list of all resources in the specified stack."""
    stack = client.describe_stacks(
        StackName=stack_name,
        RegionName=region_name
    )
    return stack['StackResources']

def get_resource_physical_id(client, stack_name, resource_type, resource_name, region_name):
    """Retrieve the physical ID of a resource in the specified stack."""
    stack_resources = get_stack_resources(client, stack_name, region_name)
    for resource in stack_resources:
        if resource['ResourceType'] == resource_type and resource['ResourceName'] == resource_name:
            return resource['PhysicalResourceId']
    return None

def update_resource_metadata(client, stack_name, resource_type, resource_name, metadata, region_name):
    """Update the metadata of a resource in the specified stack."""
    stack_resources = get_stack_resources(client, stack_name, region_name)
    for resource in stack_resources:
        if resource['ResourceType'] == resource_type and resource['ResourceName'] == resource_name:
            resource['Metadata'] = metadata
            client.update_stack_resources(
                StackName=stack_name,
                RegionName=region_name,
                StackResourceRequests=[
                    {
                        'Action': 'UPDATE',
                        'ResourceProperties': resource
                    }
                ]
            )
            return
    print("Resource not found")

# Example usage
cloudformation = boto3.client('cloudformation', region_name='us-west-2')
stacks = get_stacks(cloudformation, 'us-west-2')
for stack in stacks:
    print(stack['StackName'])

