class DuckDuckGoAPI:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = 'https://duckduckgo.com/api?'

    def search(self, query, params=None):
        url = self.base_url
        params = params or {}
        params['q'] = query
        params['api_key'] = self.api_key

        response = requests.get(url, params=params)
        response.raise_for_status()

        return response.json()

    def search_words(self, query):
        return self.search(query, params={'format': 'json'})

    def search_documents(self, query):
        return self.search(query, params={'format': 'json', 'type': 'docs'})

    def search_images(self, query):
        return self.search(query, params={'format': 'json', 'type': 'image'})

    def search_news(self, query):
        return self.search(query, params={'format': 'json', 'type': 'news'})

    def search_maps(self, query):
        return self.search(query, params={'format': 'json', 'type': 'map'})

    def translate(self, text, target_language):
        return self.search(f'translate:{text} to {target_language}', params={'format': 'json'})

# Example usage
