import sphinx
from sphinx import addnodes
from sphinx.addnodes import Section, Directive

class ToggleSectionDirective(Directive):
    """Directive to toggle page content and collapse admonitions in Sphinx documentation."""

    name = 'toggle'
    ignored_namespaces = []
    option_names = []

    def run(self, content, state):
        """Run the directive to toggle page content and collapse admonitions."""
        for node in state.document.get_root().traverse():
            if isinstance(node, Section):
                if node.state == 'visible':
                    node.state = 'hidden'
                else:
                    node.state = 'visible'

        # Collapse all admonitions
        for node in state.document.get_root().traverse():
            if isinstance(node, addnodes.admonition):
                node.state = 'hidden'

def setup(app):
    """Setup the directive in the Sphinx application."""
    app.add_directive('toggle', ToggleSectionDirective)
