        with open(destination_path, 'wb') as file:
            file.write(response['file']['content'])
        print(f'File {file_name} downloaded successfully.')
    except HttpError as error:
        print(f'Error downloading file: {error}')

def delete_file(service, bucket, file_name):
    """Deletes a file from Google Cloud Storage."""
    try:
        request = service.projects().transferFiles().delete(
            projectId=PROJECT_ID,
            body={'file': {'name': file_name}}
        )
        response = request.execute()
        print(f'File {file_name} deleted successfully.')
    except HttpError as error:
        print(f'Error deleting file: {error}')

def get_mime_type(file_path):
    """Returns the MIME type of a file."""
    mime_types = {
        'text': ['txt', 'html'],
        'image': ['jpg', 'jpeg', 'png', 'gif', 'bmp'],
        'video': ['mp4', 'mov', 'avi'],
        'audio': ['mp3', 'wav']
    }
    file_extension = os.path.splitext(file_path)[1][1:]
    for type, extensions in mime_types.items():
        if file_extension in extensions:
            return f'text/{type}'
    return 'application/octet-stream'

def main():
    service = get_service()
    upload_file(service, BUCKET_TARGET, 'example.txt', 'path/to/example.txt')
    download_file(service, BUCKET_SOURCE, 'example.txt', 'path/to/downloaded/example.txt')
    delete_file(service, BUCKET_SOURCE, 'example.txt')

if __name__ == '__main__':
    main()
