class SExpr:
    def __init__(self, *args):
        self.args = args

    def __repr__(self):
        return f"SExpr({', '.join(map(str, self.args))})"

    def __eq__(self, other):
        return self.args == other.args

    def __hash__(self):
        return hash(tuple(self.args))

    def __len__(self):
        return len(self.args)

    def __getitem__(self, index):
        if isinstance(index, int):
            return SExpr(self.args[index])
        elif isinstance(index, slice):
            return SExpr(*self.args[index])
        else:
            raise TypeError("Index must be an integer or a slice")

    def __setitem__(self, index, value):
        if isinstance(index, int):
            self.args[index] = value
        elif isinstance(index, slice):
            self.args[index] = tuple(self.args[index])
        else:
            raise TypeError("Index must be an integer or a slice")

    def __delitem__(self, index):
        del self.args[index]

    def __iter__(self):
        return iter(self.args)

    def __reversed__(self):
        return reversed(self.args)

    def __contains__(self, item):
        return item in self.args

    def __add__(self, other):
        if isinstance(other, SExpr):
            return SExpr(*self.args + other.args)
        else:
            raise TypeError("Can only add SExpr instances")

    def __radd__(self, other):
        return self + other

    def __iadd__(self, other):
        self += other
        return self

    def __sub__(self, other):
        if isinstance(other, SExpr):
            return SExpr(*[x for x in self.args if x != other.args[0]])
        else:
            raise TypeError("Can only subtract SExpr instances")

    def __isub__(self, other):
        self -= other
        return self

    def __mul__(self, other):
        if isinstance(other, SExpr):
            return SExpr(*[x for x in self.args for y in other.args])
        else:
            raise TypeError("Can only multiply SExpr instances")

    def __imul__(self, other):
        self *= other
        return self

    def __truediv__(self, other):
        if isinstance(other, SExpr):
            return SExpr(*[x for x in self.args for y in other.args])
        else:
            raise TypeError("Can only divide SExpr instances")

    def __itruediv__(self, other):
        self /= other
        return self


class SExprList:
    def __init__(self, *args):
        self.args = [SExpr(*arg) for arg in args]

    def __repr__(self):
        return f"SExprList({', '.join(map(str, self.args))})"

    def __eq__(self, other):
        return self.args == other.args

    def __hash__(self):
        return hash(tuple(tuple(arg) for arg in self.args))

    def __len__(self):
        return sum(len(arg) for arg in self.args)

    def __getitem__(self, index):
        if isinstance(index, int):
            return self.args[index]
        elif isinstance(index, slice):
            return [self.args[i] for i in index]
        else:
            raise TypeError("Index must be an integer or a slice")

    def __setitem__(self, index, value):
        if isinstance(index, int):
            self.args[index] = value
        elif isinstance(index, slice):
            self.args[index] = [self.args[i] for i in index]
        else:
            raise TypeError("Index must be an integer or a slice")

    def __delitem__(self, index):
        del self.args[index]

    def __iter__(self):
        return iter(self.args)

    def __reversed__(self):
        return reversed(self.args)

    def __contains__(self, item):
        return any(item in arg for arg in self.args)

    def __add__(self, other):
        if isinstance(other, SExprList):
            return SExprList(*[self.args[i] + other.args[i] for i in range(len(self.args))])
        else:
            raise TypeError("Can only add SExprList instances")

    def __radd__(self, other):
        return self + other

    def __iadd__(self, other):
        self += other
        return self

    def __sub__(self, other):
        if isinstance(other, SExprList):
            return SExprList(*[self.args[i] - other.args[i] for i in range(len(self.args))])
        else:
            raise TypeError("Can only subtract SExprList instances")

    def __isub__(self, other):
        self -= other
        return self

    def __mul__(self, other):
        if isinstance(other, SExprList):
            return SExprList(*[self.args[i] * other.args[i] for i in range(len(self.args))])
        else:
            raise TypeError("Can only multiply SExprList instances")

    def __imul__(self, other):
