def word_separation(s):
    return ' '.join(s.split())

def compress_string(s):
    compressed = ''
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            compressed += str(count) + s[i-1]
            count = 1
    compressed += str(count) + s[-1]
    return compressed

