import ctypes

class Inotify:
    def __init__(self):
        self.lib = ctypes.CDLL('inotify')

    def _inotify_init(self):
        return self.lib.inotify_init()

    def _inotify_watch(self, fd, mask):
        return self.lib.inotify_watch(fd, mask)

    def _inotify_read(self, fd):
        return self.lib.inotify_read(fd)

    def _inotify_mask_to_names(self, mask):
        mask_names = ctypes.create_string_buffer(1024)
        self.lib.inotify_mask_to_names(mask, mask_names)
        return mask_names.value.decode('utf-8').split(',')

    def _inotify_get_events(self, fd):
        events = ctypes.c_int()
        self.lib.inotify_get_events(fd, events)
        return self._inotify_mask_to_names(events)

    def register_watch(self, path, mask, event_handler):
        fd = self._inotify_init()
        self._inotify_watch(fd, mask)
        self.lib.inotify_add_watch(fd, path.encode('utf-8'), mask)

        def _inotify_read_handler():
            events = self._inotify_get_events(fd)
            event_handler(events)

        self.lib.inotify_read(fd, _inotify_read_handler)

        return fd

    def unregister_watch(self, fd):
        self.lib.inotify_unwatch(fd)

