        create_data = {
            'fields': fields
        }
        create_response = self._soap_call(create_url, create_data)
        return create_response

    def update_record(self, object_name, id, fields):
        update_url = self.instance_url + '/services/Soap/10.0/' + object_name + '/update'
        update_data = {
            'fields': fields,
            'id': id
        }
        update_response = self._soap_call(update_url, update_data)
        return update_response

    def search_record(self, object_name, query_string):
        search_url = self.instance_url + '/services/Soap/10.0/' + object_name + '/query'
        search_data = {
            'query': query_string
        }
        search_response = self._soap_call(search_url, search_data)
        return search_response

    def _soap_call(self, url, data):
        headers = {
            'Content-Type': 'text/xml; charset=utf-8',
            'SOAPAction': 'urn:soap:namespace:Salesforce.com:10.0'
        }
        auth_data = {
            'username': self.username,
            'password': self.password,
            'securityToken': self.security_token
        }
        auth_b64 = base64.b64encode(json.dumps(auth_data).encode()).decode()
        headers['Authorization'] = 'Basic ' + auth_b64
        response = requests.post(url, headers=headers, data=json.dumps(data), timeout=30)
        response.raise_for_status()
        return response.text
