class SemVer:
    def __init__(self, major, minor, patch):
        self.major = major
        self.minor = minor
        self.patch = patch

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __eq__(self, other):
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __lt__(self, other):
        if self.major < other.major:
            return True
        elif self.major > other.major:
            return False
        elif self.minor < other.minor:
            return True
        elif self.minor > other.minor:
            return False
        else:
            return self.patch < other.patch

    def increment_major(self):
        self.major += 1
        self.minor = 0
        self.patch = 0

    def increment_minor(self):
        self.minor += 1
        self.patch = 0

    def increment_patch(self):
        self.patch += 1

    def decrement_major(self):
        self.major -= 1
        self.minor = 0
        self.patch = 0

    def decrement_minor(self):
        self.minor -= 1
        self.patch = 0

    def decrement_patch(self):
        self.patch -= 1

    def is_valid(self):
        return self.major >= 0 and self.minor >= 0 and self.patch >= 0


class SemVerManager:
    def __init__(self):
        self.versions = {}

    def add_version(self, name, version):
        if name not in self.versions:
            self.versions[name] = SemVer(version.major, version.minor, version.patch)
        else:
            existing_version = self.versions[name]
            if existing_version < version:
                self.versions[name] = version

    def remove_version(self, name):
        if name in self.versions:
            del self.versions[name]

    def get_version(self, name):
        if name in self.versions:
            return self.versions[name]
        else:
            return None

    def list_versions(self):
        return list(self.versions.values())

    def increment_version(self, name, step='patch'):
        if name in self.versions:
            version = self.versions[name]
            if step == 'major':
                version.increment_major()
            elif step == 'minor':
                version.increment_minor()
            elif step == 'patch':
                version.increment_patch()
            else:
                raise ValueError("Invalid step. Use 'major', 'minor', or 'patch'.")
            self.add_version(name, version)
        else:
            raise ValueError("Version not found.")


# Example usage:

manager = SemVerManager()

manager.add_version('my_project', SemVer(1, 2, 3))
manager.add_version('my_project', SemVer(1, 2, 4))

print(manager.list_versions())

manager.increment_version('my_project', 'minor')
print(manager.list_versions())

manager.increment_version('my_project', 'patch')
print(manager.list_versions())

manager.remove_version('my_project')

print(manager.list_versions())
