import os
import psutil
import sys

class Cpuset:
    def __init__(self):
        self.cpus = []

    def add_cpu(self, cpu):
        self.cpus.append(cpu)

    def remove_cpu(self, cpu):
        self.cpus.remove(cpu)

    def add_task(self, task, cpu):
        for i, cpu_num in enumerate(self.cpus):
            if cpu_num == cpu:
                task.cpuAffinity = [cpu]
                break

    def remove_task(self, task):
        for i, cpu_num in enumerate(self.cpus):
            if cpu_num == task.cpuAffinity[0]:
                task.cpuAffinity.remove(cpu_num)
                break

    def get_cpus(self):
        return self.cpus

def main():
    cpuset = Cpuset()

    if len(sys.argv) > 1:
        for arg in sys.argv[1:]:
            if arg.startswith('add_cpu:'):
                cpu = int(arg.split(':')[1])
                cpuset.add_cpu(cpu)
            elif arg.startswith('remove_cpu:'):
                cpu = int(arg.split(':')[1])
                cpuset.remove_cpu(cpu)
            elif arg.startswith('add_task:'):
                task_id = int(arg.split(':')[1])
                cpu = int(arg.split(':')[2])
                cpuset.add_task(task_id, cpu)
            elif arg.startswith('remove_task:'):
                task_id = int(arg.split(':')[1])
                cpuset.remove_task(task_id)
    else:
        print("Please provide cpu set commands as arguments")

    for cpu in cpuset.get_cpus():
        print(f"CPU set: {cpu}")

    if os.name == 'nt':
        # Windows doesn't support cpu affinity directly
        print("Warning: CPU affinity is not supported on Windows")
    else:
        try:
            for task in psutil.process_iter(['pid', 'cpu_affinity']):
                for cpu in task.info['cpu_affinity']:
                    cpuset.add_task(task.info['pid'], cpu)
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass

if __name__ == '__main__':
    main()
