def chain(*funcs):
    """
    A generator-based function chaining decorator.

    Args:
        *funcs: A variable number of functions to be chained together.

    Yields:
        The result of the last function in the chain.
    """
    def wrapper(*args, **kwargs):
        result = args[0]
        for func in funcs:
            if callable(func):
                result = func(result, *args[1:], **kwargs)
            else:
                raise TypeError(f"func must be callable, not {type(func).__name__}")
        return result
    return wrapper

# Example usage:

@chain
def double(x):
    return x * 2

@chain
def add_one(x):
    return x + 1

@chain
def square(x):
    return x ** 2

result = double(5).add_one().square()
print(result)  # Output: 121
