# Custom Token Model
class CustomToken(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    token = models.CharField(max_length=255, unique=True)
    created_at = models.DateTimeField(auto_now_add=True)

    def __str__(self):
        return f"Token for {self.user.username}"

# Custom Authenticator Class
class GoogleAuthenticator:
    def __init__(self, user):
        self.user = user
        self.app_id = settings.GOOGLE_AUTH_APP_ID
        self.app_secret = settings.GOOGLE_AUTH_APP_SECRET
        self.scopes = settings.GOOGLE_AUTH_SCOPES
        self.token = None

    def generate_token(self):
        flow = InstalledAppFlow.from_client_secrets_file(
            settings.GOOGLE_AUTH_APP_CREDENTIALS,
            self.scopes
        )
        self.token = flow.run_local_server(port=0)
        return self.token

    def verify_token(self, token):
        try:
            self.token = flow = InstalledAppFlow.from_client_secrets_file(
                settings.GOOGLE_AUTH_APP_CREDENTIALS,
                self.scopes
            )
            credentials = flow.fetch_token(
                'https://www.googleapis.com/auth/identitytoolkit',
                token=self.token
            )
            return credentials
        except HttpError as e:
            return None

    def is_valid_token(self):
        if self.token is None:
            return False
        credentials = self.verify_token(self.token)
        if credentials is None:
            return False
        try:
            credentials.refresh(Request())
            return True
        except Exception as e:
            return False

# Custom Authenticator View
class GoogleAuthenticatorView(APIView):
    authentication_classes = [authentication.BasicAuthentication]
    permission_classes = [permissions.AllowAny]

    def post(self, request):
        user = request.user
        authenticator = GoogleAuthenticator(user)
        if authenticator.is_valid_token():
            return Response({"message": "Token is valid"})
        else:
            return Response({"message": "Token is not valid"})

# Login View
class LoginView(APIView):
    authentication_classes = [authentication.BasicAuthentication]
    permission_classes = [permissions.AllowAny]

    def post(self, request):
        username = request.data.get('username')
        password = request.data.get('password')
        user = authenticate(username=username, password=password)
        if user is not None:
            token = CustomToken.objects.create(user=user)
            return Response({"token": token.token}, status=200)
        else:
            return Response({"message": "Invalid credentials"}, status=401)

# Logout View
class LogoutView(APIView):
    authentication_classes = [authentication.TokenAuthentication]
    permission_classes = [permissions.AllowAny]

    def post(self, request):
        token = request.META.get('HTTP_AUTHORIZATION')
        if token is None:
            return Response({"message": "No token provided"}, status=401)
        try:
            token = CustomToken.objects.get(token=token)
        except CustomToken.DoesNotExist:
            return Response({"message": "Token is invalid"}, status=401)
        token.delete()
        return Response({"message": "Logged out successfully"}, status=200)

# Custom Authenticator View
class CustomAuthenticator(ObtainAuthToken):
