import boto3
from pathlib import Path
import botocore.exceptions

class S3Path(Path):
    def __init__(self, bucket, path, **kwargs):
        self.bucket = bucket
        self.path = path
        super().__init__(**kwargs)

    @property
    def exists(self):
        try:
            s3 = boto3.client('s3')
            s3.head_bucket(Bucket=self.bucket)
            return True
        except botocore.exceptions.ClientError as e:
            if e.response['Error']['Code'] == '404':
                return False
            raise

    @property
    def parent(self):
        return S3Path(self.bucket, self.parent)

    @property
    def stem(self):
        return self.name

    @property
    def suffix(self):
        return self.suffix

    @property
    def suffixes(self):
        return [self.suffix]

    def __str__(self):
        return f"s3://{self.bucket}/{self.path}"

    def __repr__(self):
        return f"S3Path('{self.bucket}', '{self.path}')"

class S3Bucket:
    def __init__(self, bucket_name):
        self.bucket_name = bucket_name
        self.objects = {}

    def list_objects(self):
        try:
            s3 = boto3.client('s3')
            response = s3.list_objects_v2(Bucket=self.bucket_name)
            objects = response['Contents']
            return [S3Object(obj['Key'], obj) for obj in objects]
        except botocore.exceptions.ClientError as e:
            if e.response['Error']['Code'] == '404':
                return []
            raise

    def get_object(self, key):
        try:
            s3 = boto3.client('s3')
            response = s3.get_object(Bucket=self.bucket_name, Key=key)
            return S3Object(key, response)
        except botocore.exceptions.ClientError as e:
            if e.response['Error']['Code'] == '404':
                raise
            raise

class S3Object:
    def __init__(self, key, obj):
        self.key = key
        self.obj = obj

def get_s3_client():
    return boto3.client('s3')

def get_s3_bucket(bucket_name):
    s3 = get_s3_client()
    try:
        s3.head_bucket(Bucket=bucket_name)
        return S3Bucket(bucket_name)
    except botocore.exceptions.ClientError as e:
        if e.response['Error']['Code'] == '404':
            return None
        raise

def list_s3_objects(bucket_name):
    bucket = get_s3_bucket(bucket_name)
    if bucket is None:
        return []
    return bucket.list_objects()

def get_s3_object(bucket_name, key):
    bucket = get_s3_bucket(bucket_name)
    if bucket is None:
        return None
    return bucket.get_object(key)
