import requests
import json
from typing import Dict, List

class PASETO:
    def __init__(self, client_id: str, client_secret: str, redirect_uri: str):
        self.client_id = client_id
        self.client_secret = client_secret
        self.redirect_uri = redirect_uri
        self.token = None

    def get_token(self) -> str:
        if not self.token:
            auth_url = f"https://auth.pasero.io/v1/oauth2/token"
            headers = {"Content-Type": "application/x-www-form-urlencoded"}
            data = {
                "grant_type": "client_credentials",
                "client_id": self.client_id,
                "client_secret": self.client_secret,
                "redirect_uri": self.redirect_uri,
            }
            response = requests.post(auth_url, headers=headers, data=data)
            if response.status_code == 200:
                self.token = response.json()["access_token"]
            else:
                raise Exception("Failed to get token")
        return self.token

    def login(self, username: str, password: str) -> str:
        if not self.token:
            raise Exception("You must get token first")
        auth_url = f"https://auth.pasero.io/v1/users/{username}"
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.get(auth_url, headers=headers)
        if response.status_code == 200:
            return response.json()["id"]
        else:
            raise Exception("Failed to login")

    def register(self, username: str, password: str) -> str:
        if not self.token:
            raise Exception("You must get token first")
        auth_url = f"https://auth.pasero.io/v1/users"
        headers = {"Authorization": f"Bearer {self.token}"}
        data = {
            "username": username,
            "password": password,
        }
        response = requests.post(auth_url, headers=headers, data=data)
        if response.status_code == 201:
            return response.json()["id"]
        else:
            raise Exception("Failed to register")

    def verify_credentials(self, username: str, password: str) -> bool:
        if not self.token:
            raise Exception("You must get token first")
        auth_url = f"https://auth.pasero.io/v1/users/{username}"
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.get(auth_url, headers=headers)
        if response.status_code == 200:
            user_data = response.json()
            return user_data["password"] == password
        else:
            raise Exception("Failed to verify credentials")

# Example usage
client_id = "your_client_id"
client_secret = "your_client_secret"
redirect_uri = "your_redirect_uri"

paseto = PASETO(client_id, client_secret, redirect_uri)

# Get token
token = paseto.get_token()
print(token)

# Login
username = "your_username"
password = "your_password"
user_id = paseto.login(username, password)
print(user_id)

# Register
new_username = "new_username"
new_password = "new_password"
new_user_id = paseto.register(new_username, new_password)
print(new_user_id)

# Verify credentials
is_valid = paseto.verify_credentials(username, password)
print(is_valid)
