from collections import defaultdict
from typing import Dict, List

class TrieNode:
    def __init__(self):
        self.children: Dict[str, 'TrieNode'] = {}
        self.end_of_word: bool = False
        self.count: int = 0

class Trie:
    def __init__(self, db_name: str, prefix_length: int = 3, cache_size: int = 100):
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()
        self.prefix_length = prefix_length
        self.cache_size = cache_size
        self.cache: Dict[str, TrieNode] = {}
        self.nodes: Dict[str, TrieNode] = {}
        self.create_table()

    def create_table(self):
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS trie (
                id INTEGER PRIMARY KEY,
                prefix TEXT NOT NULL,
                count INTEGER NOT NULL
            )
        ''')
        self.conn.commit()

    def insert(self, word: str) -> None:
        node = self.get_node(word)
        if node:
            node.count += 1
            self.cache[word] = node
            self.cache_size -= 1
            self.update_cache()
            self.conn.execute('''
                INSERT OR REPLACE INTO trie (prefix, count)
                VALUES (?, ?)
            ''', (word[:self.prefix_length], node.count))
            self.conn.commit()
        else:
            self.add_node(word)

    def add_node(self, word: str) -> None:
        node = TrieNode()
        node.children['$'] = node
        node.end_of_word = True
        self.nodes[word] = node
        self.cache[word] = node
        self.cache_size += 1
        self.conn.execute('''
            INSERT INTO trie (prefix, count)
            VALUES (?, ?)
        ''', (word[:self.prefix_length], 1))
        self.conn.commit()

    def get_node(self, word: str) -> TrieNode:
        node = self.nodes.get(word)
        if node:
            return node
        for prefix in range(self.prefix_length, 0, -1):
            prefix_word = word[:prefix]
            child_node = self.cache.get(prefix_word)
            if child_node:
                return child_node.children.get(prefix_word, None)
        return None

    def update_cache(self) -> None:
        for word in self.cache:
            node = self.cache[word]
            prefix = word[:self.prefix_length]
            child_node = self.nodes.get(prefix)
            if child_node:
                node.children = child_node.children.copy()
            else:
                node.children = {}
        self.cache.clear()
        for word in self.nodes:
            node = self.nodes[word]
            if len(node.children) > self.cache_size:
                del self.cache[word]
                self.cache_size -= 1
            self.cache[word] = node

    def delete(self, word: str) -> None:
        node = self.get_node(word)
        if node:
            self.remove_node(node, word)
            self.conn.execute('''
                DELETE FROM trie WHERE prefix = ?
            ''', (word[:self.prefix_length],))
            self.conn.commit()
        else:
            raise KeyError(f"{word} not found in the trie")

    def remove_node(self, node: TrieNode, word: str) -> None:
        if node.end_of_word:
            del self.nodes[word]
            del self.cache[word]
            self.cache_size += 1
        else:
            for child in list(node.children.values()):
                self.remove_node(child, word)
                if not child.end_of_word and len(child.children) == 0:
                    del child.children['$']
                    del self.nodes[word]
                    del self.cache[word]
                    self.cache_size += 1
                    break

    def query(self, prefix: str) -> List[str]:
        return [word for word in self.nodes if word.startswith(prefix)]

    def close(self) -> None:
        self.conn.close()

