        return os.path.isfile(self.path)

    def is_dir(self):
        return os.path.isdir(self.path)

    def rename(self, new_path):
        shutil.move(self.path, new_path)

    def delete(self):
        os.remove(self.path)

class Dir:
    def __init__(self, path):
        self.path = path

    def get_size(self):
        return sum(os.path.getsize(os.path.join(self.path, f)) for f in os.listdir(self.path))

    def exists(self):
        return os.path.exists(self.path)

    def list_files(self):
        return [File(os.path.join(self.path, f)) for f in os.listdir(self.path) if os.path.isfile(os.path.join(self.path, f))]

    def list_dirs(self):
        return [Dir(os.path.join(self.path, d)) for d in os.listdir(self.path) if os.path.isdir(os.path.join(self.path, d))]

    def delete(self):
        shutil.rmtree(self.path)
