from pytoolkit import Maybe

def is_none(maybe_value):
    """Checks if the Maybe value is None."""
    return Maybe.is_none(maybe_value)

def map_none(func, maybe_value):
    """Maps a function over the Maybe value, returning None if the value is None."""
    return Maybe.map(func, maybe_value) if not is_none(maybe_value) else Maybe.of(None)

def bind_none(maybe_value, func):
    """Binds a function to the Maybe value, returning None if the value is None."""
    return Maybe.bind(maybe_value, func) if not is_none(maybe_value) else Maybe.of(None)

def ap_none(func, maybe_value):
    """Applies a function to the Maybe value, returning None if the value is None."""
    return Maybe.ap(func, maybe_value) if not is_none(maybe_value) else Maybe.of(None)

def chain_none(maybe_value, func):
    """Chains a function to the Maybe value, returning None if the value is None."""
    return Maybe.chain(maybe_value, func) if not is_none(maybe_value) else Maybe.of(None)

def filter_none(maybe_value, predicate):
    """Filters the Maybe value using a predicate, returning None if the value is None."""
    return Maybe.filter(maybe_value, predicate) if not is_none(maybe_value) else Maybe.of(None)

def flat_map_none(maybe_value, func):
    """Flattens a Maybe value using a function, returning None if the value is None."""
    return Maybe.flat_map(maybe_value, func) if not is_none(maybe_value) else Maybe.of(None)

def all_none(maybe_values):
    """Checks if all Maybe values are None."""
    return Maybe.all(maybe_values) if not any(is_none(maybe_value) for maybe_value in maybe_values) else Maybe.of(False)

def any_none(maybe_values):
    """Checks if any Maybe value is None."""
    return Maybe.any(maybe_values) if any(is_none(maybe_value) for maybe_value in maybe_values) else Maybe.of(False)
