from typing import TypeVar, Generic, Callable, Any
from abc import ABC, abstractmethod
import requests

# Define type variables for API endpoints
T = TypeVar('T')
U = TypeVar('U')

# Abstract base class for O365 API clients
class O365Client(ABC, Generic[T, U]):
    @abstractmethod
    def get(self, endpoint: str, params: dict = None) -> Any:
        pass

    @abstractmethod
    def post(self, endpoint: str, data: dict = None) -> Any:
        pass

# Concrete subclass for Microsoft Graph API
class MicrosoftGraphClient(O365Client[T, U]):
    def __init__(self, base_url: str = 'https://graph.microsoft.com/v1.0'):
        self.base_url = base_url

    def get(self, endpoint: str, params: dict = None) -> Any:
        url = f'{self.base_url}{endpoint}'
        response = requests.get(url, params=params)
        response.raise_for_status()
        return response.json()

    def post(self, endpoint: str, data: dict = None) -> Any:
        url = f'{self.base_url}{endpoint}'
        response = requests.post(url, json=data)
        response.raise_for_status()
        return response.json()

# Concrete subclass for Azure Active Directory (AAD) API
class AADClient(O365Client[T, U]):
    def __init__(self, base_url: str = 'https://graph.microsoft.com/v1.0'):
        self.base_url = base_url

    def get(self, endpoint: str, params: dict = None) -> Any:
        url = f'{self.base_url}{endpoint}'
        response = requests.get(url, params=params)
        response.raise_for_status()
        return response.json()

    def post(self, endpoint: str, data: dict = None) -> Any:
        url = f'{self.base_url}{endpoint}'
        response = requests.post(url, json=data)
        response.raise_for_status()
        return response.json()

# Utility function to create a new instance of the desired API client
def create_client(client_type: str, base_url: str = 'https://graph.microsoft.com/v1.0') -> O365Client[T, U]:
    if client_type == 'microsoft_graph':
        return MicrosoftGraphClient(base_url)
    elif client_type == 'aad':
        return AADClient(base_url)
    else:
        raise ValueError('Unsupported client type')
