import json
import geopandas as gpd
from shapely.geometry import shape

def arcgis_to_geojson(arcgis_file_path):
    # Load the ArcGIS JSON file
    with open(arcgis_file_path, 'r') as f:
        arcgis_data = json.load(f)

    # Extract the geometric features
    features = []
    for layer in arcgis_data['layers']:
        for feature in layer['features']:
            geometry = feature['geometry']
            if geometry['type'] == 'Point':
                geometry_obj = shape(geometry['x'], geometry['y'])
            elif geometry['type'] == 'LineString':
                geometry_obj = shape(geometry['x'], geometry['y'])
            elif geometry['type'] == 'Polygon':
                geometry_obj = shape(geometry['coordinates'][0])
            elif geometry['type'] == 'MultiPoint':
                geometry_obj = [shape(p['x'], p['y']) for p in geometry['coordinates'][0]]
            elif geometry['type'] == 'MultiLineString':
                geometry_obj = [shape(l['x'], l['y']) for l in geometry['coordinates'][0]]
            elif geometry['type'] == 'MultiPolygon':
                geometry_obj = [shape(p['coordinates'][0][0]) for p in geometry['coordinates'][0]]
            else:
                raise ValueError('Unsupported geometry type')

            feature_obj = {
                'type': 'Feature',
                'geometry': {
                    'type': 'Point' if len(geometry_obj) == 2 else 'LineString' if len(geometry_obj) == 2 else 'Polygon',
                    'coordinates': geometry_obj
                },
                'properties': feature['attributes']
            }
            features.append(feature_obj)

    # Create a GeoDataFrame from the features
    gdf = gpd.GeoDataFrame(features, geometry='geometry')

    # Return the GeoDataFrame as GeoJSON
    return gdf.to_json('geojson')

# Usage
arcgis_file_path = 'path/to/arcgis_file.json'
geojson = arcgis_to_geojson(arcgis_file_path)
