from typing import Any, Callable, TypeVar, cast

T = TypeVar('T')
U = TypeVar('U')

class Result:
    def __init__(self, value: T, ok: bool):
        self.value = value
        self.ok = ok

    def map(self, f: Callable[[T], U]) -> 'Result[U, bool]':
        return Result(f(self.value), self.ok)

    def chain(self, f: Callable[[T], Result[U, bool]]) -> Result[U, bool]:
        return f(self.value)

    def __bool__(self) -> bool:
        return self.ok

    def __repr__(self) -> str:
        return f"Result(ok={self.ok}, value={self.value})"


def ok(value: T) -> Result[T, bool]:
    return Result(value, True)

def err(value: T) -> Result[T, bool]:
    return Result(value, False)

# Example usage:
result = ok(10)
print(result)  # Result(ok=True, value=10)

result = result.map(lambda x: x * 2)
print(result)  # Result(ok=True, value=20)

result = result.chain(lambda x: err(x + 1))
print(result)  # Result(ok=False, value=21)

result = err(10)
print(result)  # Result(ok=False, value=10)

result = result.map(lambda x: x + 1)
print(result)  # Result(ok=False, value=11)
