import hashlib
import random

class IPAD:
    def __init__(self):
        self.ip_dict = {}

    def insert(self, ip):
        hash_object = hashlib.sha256(ip.encode())
        ip_hash = hash_object.hexdigest()[:8]
        if ip_hash not in self.ip_dict:
            self.ip_dict[ip_hash] = [ip]
        else:
            self.ip_dict[ip_hash].append(ip)

    def delete(self, ip):
        hash_object = hashlib.sha256(ip.encode())
        ip_hash = hash_object.hexdigest()[:8]
        if ip_hash in self.ip_dict:
            if ip in self.ip_dict[ip_hash]:
                self.ip_dict[ip_hash].remove(ip)
                if len(self.ip_dict[ip_hash]) == 0:
                    del self.ip_dict[ip_hash]

    def lookup(self, ip):
        hash_object = hashlib.sha256(ip.encode())
        ip_hash = hash_object.hexdigest()[:8]
        if ip_hash in self.ip_dict:
            return self.ip_dict[ip_hash]
        else:
            return None

    def iterate(self):
        for ip_hash, ip_list in self.ip_dict.items():
            for ip in ip_list:
                yield ip

    def generate_random_ip(self):
        while True:
            ip = ".".join(str(random.randint(0, 255)) for _ in range(4))
            hash_object = hashlib.sha256(ip.encode())
            ip_hash = hash_object.hexdigest()[:8]
            if ip_hash not in self.ip_dict:
                return ip

# Example usage
ip_ad = IPAD()
ip_ad.insert("192.168.1.1")
ip_ad.insert("192.168.1.2")
print(ip_ad.lookup("192.168.1.1"))  # Output: ['192.168.1.1']
ip_ad.delete("192.168.1.1")
print(ip_ad.lookup("192.168.1.1"))  # Output: None
for ip in ip_ad.iterate():
    print(ip)
# Output:
# 192.168.1.1
# 192.168.1.2
print(ip_ad.generate_random_ip())  # Output: A random IP address
